const ACCOUNTS = {
  'admin@cmmschedule.demo': { role: 'admin', name: 'พี่ชมพู่', title: 'เจ้าหน้าที่จัดตารางสอน' },
  'mek@cmmschedule.demo': { role: 'mek', name: 'พี่เมก', title: 'เจ้าหน้าที่ดูแลห้องเรียน' }
};
const DEMO_PW = 'cmm2569';
const PAGES = { admin: ['dashboard', 'conditions', 'schedule', 'publish'], mek: ['mek-conditions', 'mek-check'] };

/* ---------------- Store: shared db (multi-device) with localStorage fallback ---------------- */
const LS = {
  get(k) { try { const v = localStorage.getItem(k); return v ? JSON.parse(v) : null; } catch (e) { return null; } },
  set(k, v) { try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) { } },
  sget(k) { try { const v = sessionStorage.getItem(k); return v ? JSON.parse(v) : null; } catch (e) { return null; } },
  sset(k, v) { try { if (v == null) sessionStorage.removeItem(k); else sessionStorage.setItem(k, JSON.stringify(v)); } catch (e) { } }
};
const TAB_ID = Math.random().toString(36).slice(2, 10);
const Store = {
  mode: 'loading', saving: 0, db: null, cache: {}, unsubs: {}, queue: {}, busy: {}, loaded: {}, deferred: {}, readOnly: false, slow: false,
  async init() {
    let db = null;
    try {
      if (window.claude && typeof window.claude.use === 'function') {
        db = await Promise.race([window.claude.use('db'), sleep(10000).then(() => null)]);
      }
    } catch (e) { db = null; }
    if (db) { this.db = db; this.mode = 'db'; } else { this.mode = 'local'; }
    if (this.mode === 'local') {
      window.addEventListener('storage', e => {
        if (!e.key || !e.key.startsWith('cmm:')) return;
        const p = e.key.slice(4); if (!(p in this.unsubs)) return;
        const inc = LS.get(e.key); const cur = this.cache[p];
        if (inc && cur && (inc.updatedAt || 0) < (cur.updatedAt || 0)) return;
        this.cache[p] = inc; scheduleRender();
      });
    }
  },
  watch(path) {
    if (this.unsubs[path]) return;
    if (this.mode === 'db') {
      const t = setTimeout(() => { if (!this.loaded[path]) { this.slow = true; scheduleRender(); } }, 10000);
      this.unsubs[path] = this.db.doc(path).onSnapshot(snap => {
        if (snap.metadata && snap.metadata.fromCache && !snap.exists && !this.loaded[path]) return;
        clearTimeout(t); this.loaded[path] = true; this.slow = false;
        const data = snap.exists ? clone(snap.data()) : null;
        // while our own write is in flight, keep the snapshot and decide after the write lands
        if (this.busy[path] || this.queue[path]) { this.deferred[path] = data; return; }
        // ignore a stale snapshot that is older than what we already have (prevents changes "jumping back")
        const cur = this.cache[path];
        if (data && cur && (data.updatedAt || 0) < (cur.updatedAt || 0)) return;
        this.cache[path] = data;
        scheduleRender();
      }, err => { clearTimeout(t); this.loaded[path] = true; this.err = err; scheduleRender(); });
    } else {
      this.cache[path] = LS.get('cmm:' + path); this.loaded[path] = true; this.unsubs[path] = () => { };
    }
  },
  unwatch(path) { if (this.unsubs[path]) { try { this.unsubs[path](); } catch (e) { } delete this.unsubs[path]; delete this.loaded[path]; } },
  async getOnce(path) {
    if (this.cache[path] !== undefined && this.unsubs[path]) return this.cache[path];
    if (this.mode === 'db') { try { const s = await this.db.doc(path).get(); return s.exists ? clone(s.data()) : null; } catch (e) { return null; } }
    return LS.get('cmm:' + path);
  },
  set(path, val) {
    if (this.readOnly) { toast('บัญชีนี้ดูได้อย่างเดียว ไม่สามารถบันทึกข้อมูลได้', 'bad'); return false; }
    val.updatedAt = Math.max(Date.now(), ((this.cache[path] || {}).updatedAt || 0) + 1);
    this.cache[path] = val;
    if (this.mode === 'db') { this.queue[path] = clone(val); this.flush(path); }
    else LS.set('cmm:' + path, val);
    return true;
  },
  async flush(path) {
    if (this.busy[path]) return; this.busy[path] = true; this.saving++; scheduleRender();
    while (this.queue[path]) {
      const v = this.queue[path]; this.queue[path] = null;
      try { await this.db.doc(path).set(v); }
      catch (e) {
        if (e && e.code === 'unavailable') { await sleep(400 + Math.random() * 600); try { await this.db.doc(path).set(v); } catch (e2) { this.fail(e2); } }
        else this.fail(e);
      }
    }
    this.busy[path] = false; this.saving = Math.max(0, this.saving - 1); this.lastSaved = Date.now();
    const dfr = this.deferred[path]; delete this.deferred[path];
    if (dfr && (dfr.updatedAt || 0) > ((this.cache[path] || {}).updatedAt || 0)) this.cache[path] = dfr;
    scheduleRender();
  },
  fail(e) {
    if (e && e.code === 'invalid_argument') { this.readOnly = true; toast('บัญชีนี้ดูได้อย่างเดียว ข้อมูลที่แก้ไม่ถูกบันทึก', 'bad'); }
    else if (e && e.code === 'quota_exceeded') toast('พื้นที่เก็บข้อมูลเต็ม บันทึกไม่สำเร็จ', 'bad');
    else toast('บันทึกไม่สำเร็จ ลองอีกครั้ง (' + (e && e.code || 'error') + ')', 'bad');
  },
  seed(docs) { Object.keys(docs).forEach(p => { const v = clone(docs[p]); this.set(p, v); }); }
};

/* ---------------- App state ---------------- */
const S = {
  session: LS.sget('cmm.session'),
  page: null, termId: LS.sget('cmm.term'),
  dl: null, user: null,
  ui: { view: {}, toasts: [], modal: null, drop: null, form: null, undo: [], hl: [], sel: null, selIssue: null, selOpt: 0, condTab: 'courses', mekTab: 'rooms', rsel: null, rmode: 'list', rfilter: null, mekSearch: '', anim: false, appear: false, pub: {} }
};
const D = {
  get termsDoc() { return Store.cache['app/terms'] || { list: [] }; },
  get terms() { return this.termsDoc.list || []; },
  get rooms() { return (Store.cache['app/rooms'] || { list: [] }).list || []; },
  get teachers() { return (Store.cache['app/teachers'] || { list: [] }).list || []; },
  get globals() { return (Store.cache['app/globals'] || { list: [] }).list || []; },
  get notifs() { return (Store.cache['app/notifs'] || { list: [] }).list || []; },
  get term() { return Store.cache['terms/' + S.termId] || null; },
  get courses() { return (Store.cache['courses/' + S.termId] || { list: [] }).list || []; },
  get entries() { const t = this.term; return t ? L.syncEntries(this.courses, t.entries || []) : []; }
};
const ctx = () => ({ rooms: D.rooms, teachers: D.teachers, globals: D.globals, courses: D.courses });
const termLabel = () => (D.term && D.term.label) || (D.terms.find(t => t.id === S.termId) || {}).label || '';
function status() {
  const t = D.term; if (!t) return 'empty';
  const st = t.status || 'empty';
  if (st === 'empty') return D.courses.length ? 'prep' : 'empty';
  return st;
}
const EDITABLE = ['empty', 'prep', 'draft', 'returned'];

function mut(path, fn) { const v = clone(Store.cache[path]) || {}; fn(v); Store.set(path, v, fn); scheduleRender(); return v; }
function acct() { const s = S.session || {}; return s.name ? { name: s.name, title: s.title || '' } : (ACCOUNTS[s.email] || { name: s.email || '', title: '' }); }
function mutTerm(fn) { return mut('terms/' + S.termId, t => { t.entries = L.syncEntries(D.courses, t.entries || []); fn(t); }); }
function mutCourses(fn) { return mut('courses/' + S.termId, c => { c.list = c.list || []; fn(c.list); }); }
function addNotif(to, text, link) {
  mut('app/notifs', n => { n.list = n.list || []; n.list.unshift({ id: uid(), to, text, at: Date.now(), read: {}, link: link || null, term: S.termId }); n.list = n.list.slice(0, 60); });
}
function logHist(t, text) { t.history = t.history || []; t.history.unshift({ at: Date.now(), text, by: S.session && acct().name }); t.history = t.history.slice(0, 40); }

function setTerm(id) {
  if (S.termId && S.termId !== id) { Store.unwatch('terms/' + S.termId); Store.unwatch('courses/' + S.termId); }
  S.termId = id; LS.sset('cmm.term', id);
  Store.watch('terms/' + id); Store.watch('courses/' + id);
  S.ui.sel = null; S.ui.selIssue = null; S.ui.undo = []; S.ui.form = null; S.ui.rsel = null;
}

/* ---------------- toasts ---------------- */
function toast(text, kind, action) {
  const id = uid();
  S.ui.toasts.push({ id, text, kind, action }); S.ui.toasts = S.ui.toasts.slice(-2);
  scheduleRender();
  setTimeout(() => { S.ui.toasts = S.ui.toasts.filter(t => t.id !== id); scheduleRender(); }, action ? 6500 : 3800);
}

function renderToasts() {
  let box = $('#toasts'); if (!box) { box = document.createElement('div'); box.id = 'toasts'; box.className = 'toasts'; document.body.appendChild(box); }
  const ids = S.ui.toasts.map(t => t.id);
  $$('.toast', box).forEach(n => { if (!ids.includes(n.dataset.id)) n.remove(); });
  S.ui.toasts.forEach(t => {
    if ($(`[data-id="${t.id}"]`, box)) return;
    const n = document.createElement('div'); n.className = 'toast' + (t.kind === 'bad' ? ' bad' : ''); n.dataset.id = t.id;
    n.innerHTML = esc(t.text) + (t.action ? `<button data-act="${t.action.act}">${esc(t.action.label)}</button>` : '');
    box.appendChild(n);
  });
}
/* ---------------- render loop with FLIP movement ---------------- */
let rq = false;
function scheduleRender() { if (rq) return; rq = true; requestAnimationFrame(() => { rq = false; render(); }); }
function render() {
  const app = $('#app'); if (!app) return;
  const anim = S.ui.anim; const from = S.ui.flipFrom;
  const first = {};
  if (anim) $$('[data-flip]').forEach(el => first[el.dataset.flip] = el.getBoundingClientRect());
  const fx = captureFocus();
  app.innerHTML = view();
  if (S.page !== S.ui._lastPage) { const pg = $('.page', app); if (pg) pg.classList.add('enter'); S.ui._lastPage = S.page; }
  if (S.ui.modal && S.ui._modalSeen !== S.ui.modal) { const mb = $('.modal-bg', app); if (mb) mb.classList.add('in'); S.ui._modalSeen = S.ui.modal; }
  if (S.ui.drop && S.ui._dropSeen !== S.ui.drop) { $$('.drop', app).forEach(d => d.classList.add('in')); }
  S.ui._dropSeen = S.ui.drop;
  renderToasts();
  restoreFocus(fx);
  if (anim) {
    $$('[data-flip]').forEach(el => {
      const id = el.dataset.flip;
      const a = (from && from.id === id) ? from.rect : first[id];
      const b = el.getBoundingClientRect();
      if (!a) { el.animate([{ opacity: 0, transform: 'scale(.85)' }, { opacity: 1, transform: 'none' }], { duration: 380, easing: 'cubic-bezier(.2,.9,.3,1.2)' }); return; }
      const dx = a.left - b.left, dy = a.top - b.top;
      if (Math.abs(dx) < 1 && Math.abs(dy) < 1 && !(from && from.id === id)) return;
      el.animate([{ transform: `translate(${dx}px,${dy}px) scale(${a.width / b.width || 1},${a.height / b.height || 1})`, transformOrigin: 'top left', zIndex: 5 }, { transform: 'none', transformOrigin: 'top left' }], { duration: 480, easing: 'cubic-bezier(.2,.8,.2,1)' });
    });
  }
  S.ui.anim = false; S.ui.flipFrom = null;
  if (S.ui.appear) setTimeout(() => { S.ui.appear = false; }, 50);
}
function captureFocus() {
  const a = document.activeElement; if (!a || !a.dataset || !(a.dataset.f || a.dataset.fid)) return null;
  return { key: a.dataset.f || a.dataset.fid, s: a.selectionStart, e: a.selectionEnd };
}
function restoreFocus(fx) {
  if (!fx) return;
  const el = $(`[data-f="${fx.key}"]`) || $(`[data-fid="${fx.key}"]`); if (!el) return;
  el.focus(); try { if (fx.s != null) el.setSelectionRange(fx.s, fx.e); } catch (e) { }
}

/* ---------------- shared components ---------------- */
function topbar() {
  const role = S.session.role; const acc = acct();
  const labels = { dashboard: 'แดชบอร์ด', conditions: 'เงื่อนไขห้องเรียน', schedule: 'จัดตาราง', publish: 'เผยแพร่', 'mek-conditions': 'เงื่อนไขการสอน', 'mek-check': 'ตรวจสอบตาราง' };
  const st = status();
  const unread = myNotifs().filter(n => !(n.read || {})[role]).length;
  const items = PAGES[role].map(p => {
    let dot = '';
    if (p === 'mek-check' && st === 'sent') dot = '<span class="dot">ใหม่</span>';
    if (p === 'schedule' && st === 'returned') dot = '<span class="dot">!</span>';
    if (p === 'publish' && st === 'confirmed') dot = '<span class="dot">1</span>';
    return `<button class="${S.page === p ? 'on' : ''}" data-act="go" data-p="${p}">${labels[p]}${dot}</button>`;
  }).join('');
  return `<header class="topbar">
    <div class="logo" data-act="go" data-p="${PAGES[role][0]}">CMMschedule</div>
    <nav class="nav">${items}</nav>
    <div class="tb-right">
      ${Store.mode === 'db' || Store.mode === 'cloud' ? `<span class="savest">${Store.saving ? '<span class="spin" style="width:12px;height:12px;border-color:rgba(255,255,255,.4);border-top-color:#fff"></span> กำลังบันทึก…' : Store.lastSaved ? '✓ บันทึกแล้ว' : ''}</span>` : ''}
      <button class="iconbtn" aria-label="การแจ้งเตือน" data-act="drop" data-d="bell">${IC.bell}${unread ? `<span class="bell-dot">${unread}</span>` : ''}</button>
      <button class="userbtn" data-act="drop" data-d="user">${esc(acc.name.replace('พี่', 'พี่ '))}${IC.chev}</button>
    </div>
    ${S.ui.drop === 'user' ? `<div class="drop" data-keep>
      <div class="hd"><b>${esc(acc.name)} · ${esc(acc.title)}</b><span>${esc(S.session.email)}</span></div>
      <div class="meta"><span class="sync ${Store.mode === 'db' || Store.mode === 'cloud' ? '' : 'off'}"></span>${Store.mode === 'cloud' ? 'ฐานข้อมูลออนไลน์ (Supabase) · เปิดหลายเครื่องเห็นข้อมูลเดียวกัน' : Store.mode === 'db' ? 'ข้อมูลซิงก์ออนไลน์ · เปิดหลายเครื่องเห็นข้อมูลเดียวกัน' : 'โหมดออฟไลน์ · บันทึกในเบราว์เซอร์นี้'}</div>
      ${role === 'admin' ? `<button class="it" data-act="modal" data-m="reset">${IC.undo} รีเซ็ตข้อมูลสาธิต</button>` : ''}
      <button class="it" data-act="logout">${IC.out} LOG OUT</button></div>` : ''}
    ${S.ui.drop === 'bell' ? bellDrop() : ''}
  </header>`;
}
function myNotifs() { const r = S.session.role; return D.notifs.filter(n => n.to === r || n.to === 'all'); }
function bellDrop() {
  const r = S.session.role; const list = myNotifs().slice(0, 25);
  return `<div class="drop" data-keep style="right:120px;width:380px">
    <div class="hd row" style="justify-content:space-between"><b>การแจ้งเตือน</b>${list.some(n => !(n.read || {})[r]) ? '<button class="link small" data-act="readAll">อ่านทั้งหมด</button>' : ''}</div>
    <div class="notif-list">${list.length ? list.map(n => `<button class="notif ${(n.read || {})[r] ? 'read' : ''}" data-act="openNotif" data-id="${n.id}"><span class="nd"></span><span><p>${esc(n.text)}</p><small>${ago(n.at)}</small></span></button>`).join('') : '<p class="muted" style="padding:18px">ยังไม่มีการแจ้งเตือน</p>'}</div></div>`;
}

const STEPS = ['บันทึกเงื่อนไข', 'จัดตาราง', 'ส่งแบบร่าง', 'ตรวจเช็คตาราง', 'เผยแพร่'];
function stepper() {
  const st = status();
  const cur = { empty: 0, prep: 0, draft: 1, returned: 1, sent: 3, confirmed: 4, published: 5 }[st];
  const sub = {};
  if (st === 'sent') sub[3] = 'รอพี่เมกตรวจ';
  if (st === 'returned') sub[1] = 'พี่เมกขอแก้ไข';
  if (st === 'confirmed') sub[4] = 'พร้อมเผยแพร่';
  if (st === 'published') sub[4] = 'เผยแพร่แล้ว';
  return `<div class="card"><h3 style="font-size:20px">สถานะตารางเรียน</h3><div class="stepper">${STEPS.map((s, i) => `<div class="step ${i < cur ? 'done' : i === cur ? 'cur' : ''}"><span class="n">${i < cur ? IC.checkL : i + 1}</span><span>${s}${sub[i] ? `<small>${sub[i]}</small>` : ''}</span></div>`).join('')}</div></div>`;
}

function statCard(t, v, s, o) {
  o = o || {};
  return `<div class="stat ${o.cls || ''}" ${o.act ? `data-act="${o.act}" ${o.data || ''}` : ''}><div class="t">${t}${o.badge || ''}</div><div class="v ${o.big ? 'big' : ''}">${v}</div><div class="s">${s || ''}</div></div>`;
}

/* view control (ชั้นปี / ห้องเรียน / ผู้สอน) */
function vstate(k, c) {
  const v = S.ui.view[k] || (S.ui.view[k] = { mode: 'year', key: 1 });
  if (v.mode === 'room' && !c.rooms.find(r => r.id === v.key)) v.key = (c.rooms[0] || {}).id;
  if (v.mode === 'teacher' && !c.teachers.find(t => t.id === v.key)) v.key = (c.teachers[0] || {}).id;
  return v;
}
function viewCtrl(k, c) {
  const v = vstate(k, c);
  let chips = '';
  if (v.mode === 'year') chips = [1, 2, 3, 4].map(y => `<button class="${v.key === y ? 'on' : ''}" data-act="vkey" data-k="${k}" data-v="${y}">ปี ${y}</button>`).join('');
  if (v.mode === 'room') chips = c.rooms.map(r => `<button class="${v.key === r.id ? 'on' : ''}" data-act="vkey" data-k="${k}" data-v="${r.id}">${r.id}</button>`).join('');
  if (v.mode === 'teacher') chips = c.teachers.map(t => `<button class="${v.key === t.id ? 'on' : ''}" data-act="vkey" data-k="${k}" data-v="${t.id}">${esc(t.name)}</button>`).join('');
  return `<div class="row" style="gap:34px;margin-bottom:16px"><div class="seg">${[['year', 'ชั้นปี'], ['room', 'ห้องเรียน'], ['teacher', 'ผู้สอน']].map(([m, l]) => `<button class="${v.mode === m ? 'on' : ''}" data-act="vmode" data-k="${k}" data-v="${m}">${l}</button>`).join('')}</div><div class="seg pill">${chips}</div></div>`;
}

const SHORT = { room: 'ห้องไม่ตรง', cap: 'ห้องจุไม่พอ', equip: 'อุปกรณ์ไม่พอ', teacher: 'อาจารย์ไม่สะดวก', global: 'ชนเงื่อนไขส่วนกลาง' };
const CLASH_SHORT = { room: 'ห้องชน', teacher: 'อาจารย์ชน', year: 'วิชาชน' };
const errShort = e => e.cat === 'clash' ? CLASH_SHORT[e.kind] : SHORT[e.cat];
const pct = t => ((t - 8) / 9.5 * 100);

/* timeline (ตารางเรียนแบบไทม์ไลน์) */
function timeline(o) {
  const c = o.ctx; const M = L.maps(c); const A = o.A;
  const v = o.v;
  const ents = o.entries.filter(e => e.d != null && e.r && M.C[e.c]).filter(e => {
    const co = M.C[e.c];
    if (v.mode === 'year') return co.year === v.key;
    if (v.mode === 'room') return e.r === v.key;
    return co.teacher === v.key;
  });
  const ticks = []; for (let h = 8; h <= 17; h++) ticks.push(`<span style="left:${pct(h)}%">${h}:00</span>`);
  const rows = L.DAYS_EN.map((dn, d) => {
    const items = ents.filter(e => e.d === d).map(e => { const co = M.C[e.c]; const p = co.parts[e.p]; const [t0, t1] = L.partTime(p.hours, e.h); return { e, co, p, t0, t1 }; }).sort((a, b) => a.t0 - b.t0 || a.e.id.localeCompare(b.e.id));
    const lanes = [];
    items.forEach(it => { let i = lanes.findIndex(end => end <= it.t0 + 0.001); if (i < 0) { i = lanes.length; lanes.push(0); } lanes[i] = it.t1; it.lane = i; });
    const h = Math.max(76, lanes.length * 70 + 10);
    // block-outs (global conditions / teacher unavailable)
    let bo = '';
    L.HALVES.forEach(hf => {
      const k = d + hf; const [a, b] = hf === 'am' ? [8.5, 12.5] : [13.5, 17.5];
      const g = c.globals.find(g => (g.slots || []).includes(k) && (v.mode !== 'year' ? (!g.years || !g.years.length) : (!g.years || !g.years.length || g.years.includes(v.key))));
      if (g) bo += `<div class="blockout" style="left:${pct(a)}%;width:${pct(b) - pct(a)}%">${esc(g.title)}</div>`;
      else if (v.mode === 'teacher') { const t = M.T[v.key]; if (t && (t.off || []).includes(k)) bo += `<div class="blockout off" style="left:${pct(a)}%;width:${pct(b) - pct(a)}%">ไม่สะดวกสอน</div>`; }
    });
    const blocks = items.map((it, i) => {
      const e = it.e; const per = A && A.per[e.id] || { errors: [], warns: [] };
      const err = per.errors.length; const note = o.notes && o.notes[e.id];
      const cls = ['blk', note ? 'noted' : '', o.editable && !e.lock ? 'edit' : '', err ? 'err' : (per.warns.length ? 'warnb' : ''), o.sel === e.id ? 'sel' : '', (o.hl || []).includes(e.id) ? 'hl' : '', o.appear ? 'appear' : ''].join(' ');
      const t = M.T[it.co.teacher] || {};
      return `<div class="${cls}" data-flip="${e.id}" data-eid="${e.id}" data-act="${o.act || 'selEntry'}" ${o.editable && !e.lock ? `data-drag="${e.id}"` : ''} style="left:calc(${pct(it.t0)}% + 2px);width:calc(${pct(it.t1) - pct(it.t0)}% - 4px);top:${4 + it.lane * 70}px;${o.appear ? `animation-delay:${(d * 4 + i) * 45}ms` : ''}" title="${esc(it.co.code + ' ' + it.co.name + ' · ' + L.timeLabel(it.p.hours, e.h))}">
        <div class="l1"><span class="code">${esc(it.co.code)}${it.co.parts.length > 1 ? ' · ' + esc(it.p.kind) : ''}</span><span class="rp">${esc(e.r)}</span></div>
        <div class="l2">${err ? `<span class="er">${IC.xc} ${esc(errShort(per.errors[0]))}</span>` : note ? `<span class="nt">✎ ${note === 1 ? 'ต้องแก้ไข' : 'หมายเหตุพี่เมก'}</span>` : `<span class="nm">${esc(it.co.name)}</span>`}<span class="tc">${esc(t.name || '')}</span></div>
        ${e.lock ? `<span class="lock">${IC.lock}</span>` : ''}</div>`;
    }).join('');
    return `<div class="tt-row" data-day="${d}"><div class="tt-day" style="min-height:${h - 6}px">${dn}</div><div class="tt-track" style="min-height:${h}px">${bo}${blocks}</div></div>`;
  }).join('');
  return `<div class="tt-wrap" ${o.id ? `id="${o.id}"` : ''}><div class="tt">
    <div class="tt-head"><div class="dl">DAY</div><div class="tt-axis">${ticks.join('')}</div></div>
    <div class="tt-body"><div style="position:absolute;left:130px;right:0;top:0;bottom:0;pointer-events:none"><div class="lunch" style="left:${pct(12.5)}%;width:${pct(13.5) - pct(12.5)}%;top:0;bottom:0"><span>LUNCH</span></div></div>${rows}</div>
    </div></div>`;
}

function emptyTimeline() { return timeline({ ctx: { rooms: [], teachers: [], globals: [], courses: [] }, entries: [], v: { mode: 'year', key: 1 }, A: null }); }

/* CMMschedule — pages */
function view() {
  let html = '';
  if (Store.mode === 'loading' || !Store.loaded['app/terms']) html = loadingView();
  else if (!Store.cache['app/terms']) html = (Store.mode === 'cloud' && !S.session && S.page !== 'public') ? loginView() : setupView();
  else if (S.page === 'public') html = publicView();
  else if (!S.session) html = loginView();
  else {
    const p = S.page;
    const body = { dashboard: dashboardView, conditions: conditionsView, schedule: scheduleView, publish: publishView, 'mek-conditions': mekCondView, 'mek-check': mekCheckView }[p];
    html = topbar() + (Store.readOnly ? '<div class="banner warn" style="border-radius:0;margin:0">บัญชีนี้ดูได้อย่างเดียว · การแก้ไขจะไม่ถูกบันทึก</div>' : '') + (Store.slow ? '<div class="banner warn" style="border-radius:0;margin:0">ยังเชื่อมต่อฐานข้อมูลไม่ได้ ข้อมูลที่เห็นอาจไม่เป็นปัจจุบัน</div>' : '') + (body ? body() : '');
  }
  return html + modalView();
}
function loadingView() { return `<div class="setup"><div class="logo" style="font-size:38px">CMMschedule</div><p class="muted" style="margin-top:20px"><span class="spin"></span> กำลังโหลดข้อมูล…</p>${Store.slow ? '<p class="muted small">เชื่อมต่อฐานข้อมูลช้ากว่าปกติ กรุณารอสักครู่</p>' : ''}</div>`; }
function setupView() {
  return `<div class="login-bg"><div class="card" style="max-width:560px;text-align:center;border:0;border-radius:22px;padding:40px">
  <div class="logo" style="font-size:38px">CMMschedule</div>
  <p style="margin:18px 0 6px;font-size:18px;color:var(--ink);font-weight:600">ระบบยังไม่มีข้อมูล</p>
  <p class="muted">โหลดข้อมูลสาธิต: รายวิชาภาค 2 ตามหลักสูตร CMM 2564 (15 วิชา) ห้องเรียน 7 ห้อง อาจารย์ 6 ท่าน ตารางภาค 2/2568 ที่เผยแพร่แล้ว และภาค 2/2569 ที่ยังไม่ได้จัด</p>
  ${Store.mode === 'cloud' && (!S.session || S.session.role !== 'admin') ? '<p class="small" style="margin-top:16px;color:var(--navy)">รอเจ้าหน้าที่จัดตาราง (Admin) เข้าสู่ระบบเพื่อตั้งค่าข้อมูลเริ่มต้น</p>' : '<button class="btn lg" style="margin-top:16px" data-act="seed">ตั้งค่าข้อมูลสาธิต</button>'}</div></div>`;
}

/* ---------------- Login ---------------- */
function loginView() {
  const f = S.ui.login || (S.ui.login = { email: '', pw: '', show: false, err: '' });
  return `<div class="login-bg"><div class="login ${f.shake ? 'shake' : ''}">
    <div class="art" style="background-image:url(${LOGIN_ART})" role="img" aria-label="CMMschedule ระบบจัดตารางสอนและห้องเรียน หลักสูตร CMM"></div>
    <form class="frm" data-form="login">
      <h1>เข้าสู่ระบบ</h1>
      <label for="em">อีเมล</label><input id="em" class="inp" type="email" autocomplete="username" data-f="login.email" value="${esc(f.email)}">
      <label for="pw">รหัสผ่าน</label><div class="pw"><input id="pw" class="inp" type="${f.show ? 'text' : 'password'}" autocomplete="current-password" data-f="login.pw" value="${esc(f.pw)}"><button type="button" aria-label="แสดงรหัสผ่าน" data-act="togglePw">${IC.eye}</button></div>
      ${f.err ? `<p class="err-msg">${esc(f.err)}</p>` : ''}
      <button class="btn lg block" type="submit" style="margin-top:6px;font-size:19px">เข้าสู่ระบบ</button>
      <div class="demo-acc">${Store.mode === 'cloud' ? '<p>เข้าสู่ระบบด้วยบัญชีที่ผู้ดูแลระบบสร้างให้</p>' : `<p>บัญชีสาธิต (รหัสผ่าน ${DEMO_PW}) · คลิกเพื่อกรอกให้</p>`}
        ${(Store.mode === 'cloud' ? [] : Object.keys(ACCOUNTS)).map(em => `<button type="button" data-act="fillAcc" data-em="${em}"><span><b>${ACCOUNTS[em].name}</b> · ${ACCOUNTS[em].title}<br><span>${em}</span></span>${IC.chevR}</button>`).join('')}
        <button type="button" data-act="go" data-p="public" style="background:#fff"><span><b>ดูตารางเรียนที่เผยแพร่</b><br><span>สำหรับอาจารย์และนักศึกษา · ไม่ต้องเข้าสู่ระบบ</span></span>${IC.chevR}</button>
      </div>
    </form></div></div>`;
}

/* ---------------- Admin: Dashboard ---------------- */
function termSelect() {
  return `<div class="row"><label class="muted small" for="tsel">ภาคเรียน</label><select id="tsel" class="inp" style="width:150px;min-height:38px" data-act-change="setTerm">${D.terms.map(t => `<option value="${t.id}" ${t.id === S.termId ? 'selected' : ''}>${t.label}</option>`).join('')}</select>
  <button class="btn ghost sm" data-act="modal" data-m="newTerm">${IC.plus} ภาคเรียนใหม่</button></div>`;
}
function nextBanner() {
  const st = status(); const t = D.term || {};
  const map = {
    empty: null,
    prep: ['info', 'มีรายวิชาแล้ว ' + D.courses.length + ' วิชา · ยังไม่ได้จัดตาราง', 'ตรวจข้อมูลให้ครบแล้วกดจัดตารางอัตโนมัติ', 'conditions', 'ไปหน้าเงื่อนไขห้องเรียน'],
    draft: ['info', 'กำลังจัดตาราง (แบบร่าง)' + (t.copiedFrom ? ' · ใช้ตาราง ' + t.copiedFrom + ' เป็นต้นแบบ' : ''), 'แก้จุดชนให้หมดแล้วส่งแบบร่างให้พี่เมกตรวจ', 'schedule', 'ไปหน้าจัดตาราง'],
    returned: ['red', 'พี่เมกส่งกลับให้แก้ไข ' + (t.returnNotes || []).filter(n => !n.done).length + ' คาบ', 'ดูหมายเหตุและแก้ไขในหน้าจัดตาราง', 'schedule', 'ไปแก้ไข'],
    sent: ['warn', 'ส่งแบบร่างฉบับที่ ' + (t.version || 1) + ' แล้ว · รอพี่เมกตรวจสอบ', t.sentAt ? 'ส่งเมื่อ ' + thDT(t.sentAt) : '', null, null],
    confirmed: ['ok', 'พี่เมกยืนยันตารางแล้ว · พร้อมเผยแพร่', 'ส่งอีเมลแจ้งอาจารย์และ Export ไฟล์ได้หลังเผยแพร่', 'publish', 'ไปหน้าเผยแพร่'],
    published: ['ok', 'เผยแพร่ตารางแล้ว', t.published ? 'เมื่อ ' + thDT(t.published.at) : '', 'publish', 'ดูหน้าเผยแพร่']
  }[st];
  if (!map) return '';
  return `<div class="banner ${map[0]}"><div class="grow"><b>${esc(map[1])}</b><span class="small">${esc(map[2] || '')}</span></div>${map[3] ? `<button class="btn sm" data-act="go" data-p="${map[3]}">${map[4]} ${IC.chevR}</button>` : ''}</div>`;
}
function daysLeft() {
  const t = D.term || D.terms.find(x => x.id === S.termId) || {};
  if (!t.startDate) return ['–', ''];
  const start = new Date(t.startDate + 'T00:00:00'); const today = new Date(); today.setHours(0, 0, 0, 0);
  const n = Math.round((start - today) / 864e5);
  return n >= 0 ? [n + ' วัน', 'เปิดภาคเรียน ' + thDate(start)] : ['เปิดแล้ว', 'เปิดภาคเรียน ' + thDate(start)];
}
function dashboardView() {
  const st = status(); const c = ctx(); const ents = D.entries; const A = L.analyze(c, ents);
  const t = D.term || {};
  const has = A.placed.length > 0;
  const [dl, ds] = daysLeft();
  let tt;
  if (st === 'empty') tt = emptyState();
  else if (!has) tt = `<div class="empty" style="margin-bottom:18px"><span style="color:var(--navy)">${IC.cal}</span><h3>ยังไม่ได้จัดตารางเรียนภาค ${esc(termLabel())}</h3><p class="muted">มีรายวิชา ${D.courses.length} วิชาพร้อมแล้ว</p><div class="row" style="justify-content:center;margin-top:12px"><button class="btn ghost" data-act="go" data-p="conditions">ตรวจข้อมูลก่อนจัด</button><button class="btn" data-act="startAuto">จัดตารางอัตโนมัติ</button></div></div><div class="ghost-grid">${emptyTimeline()}</div>`;
  else tt = viewCtrl('dash', c) + timeline({ ctx: c, entries: ents, v: vstate('dash', c), A, act: 'dashEntry' });
  return `<main class="page">
    <div class="ph"><div><h1>แดชบอร์ด</h1><p>ภาคเรียนที่ ${esc(termLabel())} ${t.updatedAt ? 'Update ' + thDate(t.updatedAt) : ''}</p></div><div class="actions">${termSelect()}</div></div>
    ${nextBanner()}
    ${stepper()}
    <div class="grid g3" style="margin-top:44px">
      ${statCard('จุดชนภายในตาราง', has ? A.stats.conflicts : '–', has ? (A.stats.conflicts ? 'พบจุดชน · แก้ไขในหน้าจัดตาราง' : 'ไม่พบจุดชนภายในตาราง') : 'ยังไม่มีตาราง', { big: 1, cls: has && A.stats.conflicts ? 'alert click' : '', act: has && A.stats.conflicts ? 'go' : '', data: 'data-p="schedule"' })}
      ${statCard('รายวิชาที่ลงตาราง', has ? A.stats.courseDone : (D.courses.length ? 0 : '–'), D.courses.length ? (A.stats.courseDone === A.stats.courses ? 'รายวิชาครบถ้วน' : 'จาก ' + A.stats.courses + ' วิชา · ยังไม่ได้ลง ' + (A.stats.courses - A.stats.courseDone) + ' วิชา') : 'ยังไม่มีรายวิชา', { big: 1 })}
      ${statCard('เหลือเวลาก่อนเปิดภาคเรียน', dl, ds, { big: 1 })}
    </div>
    <h2 class="h2" style="margin-top:44px">ตารางเรียน</h2>
    ${tt}
  </main>`;
}
function emptyState() {
  const srcs = D.terms.filter(t => t.id !== S.termId);
  const src = S.ui.copySrc || (srcs[srcs.length - 1] || {}).id;
  return `<div class="empty" style="margin-bottom:22px">
    <span style="color:var(--navy)">${IC.cal}</span>
    <h3>ยังไม่มีตารางเรียนของภาคเรียน ${esc(termLabel())}</h3>
    <p class="muted" style="margin:0 0 20px">เลือกวิธีเริ่มต้นจัดตาราง</p>
    <div class="grid g2" style="max-width:900px;margin:0 auto">
      <div class="choice"><span class="ic">${IC.copy}</span><h4>ใช้ตารางเดิมเป็นต้นแบบ</h4><p>คัดลอกรายวิชาและคาบเรียนจากภาคก่อน แล้วระบบตรวจกับเงื่อนไขล่าสุดให้ทันที เหมาะเมื่อรายวิชาส่วนใหญ่เหมือนเดิม</p>
        ${srcs.length ? `<div class="row" style="margin-top:auto"><select class="inp" style="width:140px;min-height:40px" data-act-change="copySrc">${srcs.map(t => `<option value="${t.id}" ${t.id === src ? 'selected' : ''}>${t.label}</option>`).join('')}</select><button class="btn" data-act="copyTerm" data-src="${src}">คัดลอกตารางเดิม</button></div>` : '<p class="small muted">ยังไม่มีภาคเรียนก่อนหน้า</p>'}</div>
      <div class="choice"><span class="ic">${IC.book}</span><h4>เริ่มใหม่จากหลักสูตร</h4><p>นำเข้ารายวิชาจากไฟล์ Excel ของเล่มหลักสูตร ให้พี่เมกบันทึกเงื่อนไขห้อง แล้วให้ระบบจัดตารางอัตโนมัติ</p>
        <div class="row" style="margin-top:auto"><button class="btn teal" data-act="modal" data-m="import">${IC.dl} นำเข้าข้อมูลรายวิชา</button></div></div>
    </div></div>
    <p class="small muted" style="margin:0 0 8px">ตัวอย่างหน้าตาตารางเมื่อจัดเสร็จ</p><div class="ghost-grid">${emptyTimeline()}</div>`;
}

/* ---------------- Admin: เงื่อนไขห้องเรียน ---------------- */
function roomEquipText(r) {
  const a = [];
  if (r.mac) a.push('Mac ' + r.mac + ' เครื่อง');
  if (r.win) a.push('Windows ' + r.win + ' เครื่อง');
  const b = []; if (r.projector) b.push('โปรเจกเตอร์'); if (r.mic) b.push('ไมค์');
  return (a.concat(b)).join(', ') || (r.note || '–');
}
function roomStatusText(r) {
  if (r.status === 'closed') return `<span class="bad-c">งดใช้${r.closedUntil ? 'ถึง ' + esc(r.closedUntil) : ''}</span>`;
  if (r.broken) return `<span style="color:var(--amber)">เสีย ${r.broken} เครื่อง</span>`;
  return 'พร้อมใช้';
}
const roomComplete = r => !!(r.id && r.type && r.cap);
const offText = t => (t.off || []).length ? t.off.map(k => L.DAYS_SHORT[+k[0]] + ' ' + (k.slice(1) === 'am' ? 'เช้า' : 'บ่าย')).join(', ') : '-';
function conditionsView() {
  const courses = D.courses; const rooms = D.rooms; const teachers = D.teachers;
  const cs = courses.filter(c => c.saved).length; const rs = rooms.filter(roomComplete).length;
  const usedT = teachers.filter(t => courses.some(c => c.teacher === t.id));
  const ts = usedT.filter(t => t.saved).length;
  const tab = S.ui.condTab;
  const editable = EDITABLE.includes(status());
  let body = '';
  if (tab === 'courses') {
    body = courses.length ? `<table class="tbl lined"><thead><tr><th>รายวิชา</th><th>ชั้นปี</th><th>นศ.</th><th>รูปแบบ / ห้อง</th><th>อาจารย์</th><th>สถานะข้อมูล</th></tr></thead><tbody>
      ${courses.map(c => `<tr class="click" data-act="modal" data-m="course" data-id="${c.id}"><td>${esc(c.code)} ${esc(c.name)}${c.credit ? ' <span class="cr">' + esc(c.credit) + '</span>' : ''}${c.elective ? ' <span class="badge grey">เลือก</span>' : ''}</td><td>${c.year}</td><td>${c.students}</td><td>${c.parts.map(p => p.type === 'บรรยาย' ? 'เลคเชอร์' : p.type === 'คอมพิวเตอร์' ? 'แล็บคอมฯ' : p.type).join(' + ')}${c.parts.some(p => p.room) ? ' <span class="small muted">(' + c.parts.filter(p => p.room).map(p => p.room).join(', ') + ')</span>' : ''}</td><td style="white-space:nowrap">${esc((teachers.find(t => t.id === c.teacher) || {}).name || '-')}</td><td>${c.saved ? (c.parts.some(p => p.room || (p.equip || []).length) || c.note ? 'มีเงื่อนไข' : 'บันทึกแล้ว') : '<span class="bad-c">รอพี่เมกบันทึก</span>'}</td></tr>`).join('')}</tbody></table>
      <button class="link small" style="margin-top:8px" data-act="modal" data-m="course">+ เพิ่มรายวิชา</button>`
      : `<div style="padding:30px;text-align:center" class="muted">ยังไม่มีรายวิชาในภาคเรียนนี้<br><button class="btn teal" style="margin-top:12px" data-act="modal" data-m="import">${IC.dl} นำเข้าข้อมูลหลักสูตร / รายวิชา</button></div>`;
  } else if (tab === 'rooms') {
    body = `<table class="tbl lined"><thead><tr><th>ห้อง</th><th>ประเภท</th><th>ความจุ</th><th>อุปกรณ์</th><th>สถานะ</th></tr></thead><tbody>${rooms.map(r => `<tr><td>${r.id}</td><td>${L.ROOM_TYPE_LABEL[r.type]}</td><td>${r.cap}</td><td>${esc(roomEquipText(r))}</td><td>${roomStatusText(r)}</td></tr>`).join('')}</tbody></table><p class="small muted">ข้อมูลห้องเรียนดูแลและแก้ไขโดยพี่เมก (เจ้าหน้าที่ดูแลห้องเรียน)</p>`;
  } else {
    body = `<table class="tbl lined"><thead><tr><th>อาจารย์</th><th>ช่วงที่สอนไม่ได้</th><th>เงื่อนไข</th></tr></thead><tbody>${teachers.map(t => `<tr><td>${esc(t.name)}${t.title ? ' · ' + esc(t.title) : ''}${t.saved ? '' : ' <span class="badge red">ยังไม่บันทึก</span>'}</td><td>${offText(t)}</td><td>${esc((t.conds || []).join(' · ') || '-')}</td></tr>`).join('')}</tbody></table><p class="small muted">พี่เมกเป็นผู้สอบถามอาจารย์และบันทึกเงื่อนไขการสอน</p>`;
  }
  const g = D.globals;
  return `<main class="page">
    <div class="ph"><div><h1>เงื่อนไขห้องเรียน</h1><p>รวมข้อมูลรายวิชา ห้องเรียน และเงื่อนไขทั้งหมดก่อนจัดตาราง · ภาคเรียน ${esc(termLabel())}</p></div></div>
    <div class="card" style="padding:18px 54px 26px">
      <div class="row" style="justify-content:space-between"><h3 style="font-size:21px">ตรวจสอบข้อมูลก่อนจัดตาราง</h3><button class="btn teal" data-act="modal" data-m="import">${IC.dl} นำเข้าข้อมูลหลักสูตร / รายวิชา</button></div>
      <div class="grid g3" style="margin-top:14px">
        ${checkCard(cs, courses.length, 'รายวิชา', 'courses')}
        ${checkCard(rs, rooms.length, 'ห้องเรียน', 'rooms')}
        ${checkCard(ts, usedT.length, 'อาจารย์', 'teachers')}
      </div></div>
    <div style="display:grid;grid-template-columns:minmax(0,1fr) 425px;gap:56px;margin-top:28px;align-items:start">
      <div class="tabcard"><div class="tabbar">${[['courses', 'รายวิชา'], ['rooms', 'ห้องเรียน'], ['teachers', 'เงื่อนไขอาจารย์']].map(([k, l]) => `<button class="${tab === k ? 'on' : ''}" data-act="condTab" data-v="${k}">${l}</button>`).join('')}</div><div class="in">${body}</div></div>
      <div class="panel" style="padding:24px 30px"><h3 style="font-size:18px">เงื่อนไขส่วนกลาง</h3>
        ${g.map(x => `<button class="gcard" data-act="modal" data-m="global" data-id="${x.id}"><b>${esc(x.title)}</b>${esc(slotText(x.slots))}${x.years && x.years.length ? ' · ปี ' + x.years.join(', ') : ' · ทุกชั้นปี'}<br><span class="small">${esc(x.note || '')}</span></button>`).join('')}
        <button class="gadd" data-act="modal" data-m="global">+ &nbsp; เพิ่มเงื่อนไขส่วนกลาง</button></div>
    </div>
    <div class="bar" style="margin-top:22px;padding:12px 30px"><span class="spacer">ระบบจะดึงข้อมูลทั้งหมดในหน้านี้ไปใช้จัดตาราง${cs < courses.length ? ` · <span class="bad-c">ยังขาดเงื่อนไขห้อง ${courses.length - cs} วิชา</span>` : ''}</span>
      <button class="btn lg" ${!courses.length || !editable ? 'disabled' : ''} title="${!editable ? 'ตารางถูกส่งแบบร่าง/เผยแพร่แล้ว' : ''}" data-act="startAuto">จัดตารางอัตโนมัติ</button></div>
  </main>`;
}
function checkCard(n, total, label, tab) {
  const miss = total - n;
  return `<div class="stat click ${S.ui.condTab === tab ? 'sel' : ''}" data-act="condTab" data-v="${tab}" style="padding:16px 26px"><div class="small" style="color:${miss ? 'var(--red-d)' : 'var(--ink)'}">${total ? (miss ? 'ขาด ' + miss + (label === 'รายวิชา' ? ' วิชา' : label === 'ห้องเรียน' ? ' ห้อง' : ' ท่าน') : 'ครบแล้ว') : 'ยังไม่มีข้อมูล'}</div><div style="font-size:24px;font-weight:700;color:var(--ink)">${label} <span style="font-size:40px;font-weight:500">${String(n).padStart(2, '0')} / ${String(total).padStart(2, '0')}</span></div></div>`;
}
const slotText = slots => (slots || []).map(k => 'ทุก' + L.DAYS[+k[0]] + (k.slice(1) === 'am' ? 'เช้า' : 'บ่าย')).join(', ');

/* ---------------- Admin: จัดตาราง ---------------- */
function scheduleView() {
  const st = status(); const c = ctx(); const ents = D.entries; const A = L.analyze(c, ents); const t = D.term || {};
  const editable = EDITABLE.includes(st);
  const canSend = editable && A.stats.conflicts === 0 && A.unplaced.length === 0 && A.placed.length > 0;
  const notesOpen = st === 'returned' ? (t.returnNotes || []).filter(n => !n.done) : [];
  const v = vstate('sch', c);
  let banner = '';
  if (st === 'sent') banner = `<div class="banner warn"><div class="grow"><b>ส่งแบบร่างฉบับที่ ${t.version} ให้พี่เมกแล้ว · ตารางล็อกระหว่างรอตรวจ</b><span class="small">ถ้าต้องการแก้ไข ให้ดึงแบบร่างกลับมาก่อน (พี่เมกจะได้รับแจ้งเตือน)</span></div><button class="btn ghost sm" data-act="recall">ดึงแบบร่างกลับมาแก้ไข</button></div>`;
  if (st === 'confirmed') banner = `<div class="banner ok"><div class="grow"><b>พี่เมกยืนยันตารางทั้งหมดแล้ว</b><span class="small">ไปหน้าเผยแพร่เพื่อเผยแพร่ ส่งอีเมล และ Export ไฟล์</span></div><button class="btn ghost sm" data-act="modal" data-m="reopen">แก้ไขตารางอีกครั้ง</button><button class="btn sm" data-act="go" data-p="publish">ไปหน้าเผยแพร่ ${IC.chevR}</button></div>`;
  if (st === 'published') banner = `<div class="banner ok"><div class="grow"><b>ตารางนี้เผยแพร่แล้ว</b><span class="small">การแก้ไขรอบใหม่ต้องส่งให้พี่เมกตรวจและเผยแพร่ใหม่อีกครั้ง</span></div><button class="btn ghost sm" data-act="modal" data-m="reopen">เริ่มแก้ไขรอบใหม่</button></div>`;
  if (st === 'returned') banner = `<div class="banner red"><div class="grow"><b>พี่เมกส่งกลับให้แก้ไข ${notesOpen.length} คาบ</b>${(t.returnNotes || []).map(n => `<div class="small" style="margin-top:4px">${n.done ? '✓' : '•'} <b style="display:inline">${esc(n.code)}</b> ${esc(n.note || 'ต้องแก้ไข')} ${n.done ? '' : `<button class="link small" data-act="pickEntry" data-id="${n.eid}">ดูคาบ</button> · <button class="link small" data-act="noteDone" data-id="${n.eid}">แก้แล้ว</button>`}</div>`).join('')}</div></div>`;
  if (t.copiedFrom && st === 'draft' && !t.sentAt) banner = `<div class="banner info"><div class="grow"><b>ใช้ตาราง ${esc(t.copiedFrom)} เป็นต้นแบบ</b><span class="small">ระบบตรวจตารางเดิมกับเงื่อนไขล่าสุดแล้ว รายการที่ขัดแย้งแสดงใน "รายงานปัญหาที่พบ" · ลากคาบเพื่อย้าย หรือให้ AI เสนอทางแก้</span></div></div>`;
  if (!D.courses.length) return `<main class="page"><div class="ph"><div><h1>จัดตาราง</h1><p>จัดตารางเรียนภาคเรียนที่ ${esc(termLabel())}</p></div></div>${stepper()}<div class="empty" style="margin-top:30px"><h3>ยังไม่มีรายวิชาสำหรับจัดตาราง</h3><p class="muted">เริ่มจากคัดลอกตารางเดิมในแดชบอร์ด หรือนำเข้ารายวิชาจากหลักสูตร</p><div class="row" style="justify-content:center"><button class="btn ghost" data-act="go" data-p="dashboard">ไปแดชบอร์ด</button><button class="btn teal" data-act="modal" data-m="import">นำเข้าข้อมูลรายวิชา</button></div></div></main>`;

  return `<main class="page">
    <div class="ph"><div><h1>จัดตาราง</h1><p>จัดตารางเรียนภาคเรียนที่ ${esc(termLabel())}${t.version ? ' · แบบร่างฉบับที่ ' + (t.version + (editable ? 1 : 0)) : ''}</p></div>
      <div class="actions">${S.ui.undo.length && editable ? `<button class="btn ghost" data-act="undo">${IC.undo} ย้อนกลับ</button>` : ''}
      <button class="btn teal" ${editable ? '' : 'disabled'} data-act="startAuto">จัดตารางใหม่</button>
      <button class="btn ghost" ${canSend ? '' : 'disabled'} title="${canSend ? '' : 'ต้องไม่มีจุดชนและจัดวางครบทุกวิชาก่อน'}" data-act="modal" data-m="send">ส่งต่อแบบร่าง ${IC.chevR}</button></div></div>
    ${banner}
    ${stepper()}
    <div class="grid g4" style="margin-top:34px">
      ${statCard('รายวิชาที่ลงตาราง', A.stats.courseDone + '/' + A.stats.courses + ' วิชา', '')}
      ${statCard('จุดชนที่พบ', A.stats.conflicts + ' จุดชน', '', { cls: A.stats.conflicts ? 'alert' : '' })}
      ${statCard('ยังจัดไม่ได้', A.stats.unplacedCourses + ' วิชา', '', { cls: A.stats.unplacedCourses ? 'alert' : '' })}
      ${statCard('ตรงตามเงื่อนไข', A.stats.okPct + '%', '')}
    </div>
    <div class="sch-grid" style="margin-top:34px">
      <div>
        <h2 class="h2" style="margin-top:0">ตารางเรียน</h2>
        ${viewCtrl('sch', c)}
        ${editable ? `<p class="small muted" style="margin:-6px 0 10px">ลากคาบเรียนไปวางช่องอื่นเพื่อย้าย (ช่องสีเขียว = วางได้ไม่ชน, สีแดง = ชน) · คลิกคาบเพื่อดูเหตุผลและเปลี่ยนห้อง</p>` : ''}
        ${timeline({ ctx: c, entries: ents, v, A, editable, sel: S.ui.sel, hl: S.ui.hl, id: 'tt-main', appear: S.ui.appear, notes: notesMap(t) })}
        ${unplacedBar(A, c, editable)}
        ${explainPanel(A, c, ents, editable)}
      </div>
      <div>${issuesPanel(A, c, ents, editable, t)}</div>
    </div>
  </main>`;
}
function notesMap(t) { const m = {}; if (status() === 'returned') (t.returnNotes || []).forEach(n => { if (!n.done) m[n.eid] = n.note || 'ต้องแก้ไข'; }); return m; }
function unplacedBar(A, c, editable) {
  const M = L.maps(c);
  if (!A.unplaced.length) return `<div class="bar"><span class="ic-ok" style="width:30px;height:30px;background:var(--navy)">${IC.check}</span><span class="small" style="color:var(--navy)">รายวิชาทั้งหมดถูกจัดวางลงตารางเรียบร้อย</span></div>`;
  return `<div class="bar"><span style="color:var(--navy)">${IC.info}</span><span class="small" style="color:var(--navy)">แจ้งเตือนรายวิชาที่ยังไม่ถูกจัดวาง${editable ? ' · ลากชิปลงตาราง หรือคลิกให้ AI หาที่ว่าง' : ''}</span>
    ${A.unplaced.map(e => { const co = M.C[e.c]; return `<button class="uchip" data-act="pickIssue" data-id="unplaced:${e.id}" ${editable ? `data-drag="${e.id}"` : ''}>${esc(co.code)}${co.parts.length > 1 ? ' · ' + esc(co.parts[e.p].kind) : ''}</button>`; }).join('')}</div>`;
}
function explainPanel(A, c, ents, editable) {
  const e = ents.find(x => x.id === S.ui.sel);
  if (!e || e.d == null) return `<div class="explain"><h4>อธิบายแนวทางที่แนะนำ</h4><p class="muted small" style="margin:0">คลิกคาบเรียนในตารางเพื่อดูว่าทำไมระบบจัดไว้แบบนี้ และย้ายวัน/เวลา/ห้องเองได้</p></div>`;
  const M = L.maps(c); const co = M.C[e.c]; const p = co.parts[e.p]; const t = M.T[co.teacher] || {};
  const rs = L.reasons(c, ents, e);
  const others = ents.filter(o => o.id !== e.id && o.d != null && o.r);
  const roomOpts = c.rooms.map(r => { const pr = L.placementProblems(c, M, others, e, e.d, e.h, r.id); return `<option value="${r.id}" ${r.id === e.r ? 'selected' : ''}>${r.id} · ${L.ROOM_TYPE_LABEL[r.type].replace('ห้อง', '')} ${r.cap} คน ${pr.length ? '✗ ' + errShort(pr[0]) : '✓'}</option>`; }).join('');
  return `<div class="explain">
    <div class="row" style="justify-content:space-between;align-items:flex-start"><div><h4>อธิบายแนวทางที่แนะนำ</h4><div style="font-weight:700;color:var(--navy);font-size:17px">วิชา ${esc(co.code)} ${esc(co.name)}${co.parts.length > 1 ? ' (คาบ' + esc(p.kind) + ')' : ''}</div>
    <div class="small muted">${L.DAYS[e.d]} ${L.timeLabel(p.hours, e.h)} · ห้อง ${e.r} · ${esc(t.name || '')} · ปี ${co.year} · ${co.students} คน · ${co.credit ? 'หน่วยกิต ' + esc(co.credit) + ' = ' : ''}${p.hours} ชม./สัปดาห์</div></div>
    <button class="x" aria-label="ปิด" data-act="selEntry" data-eid="">${IC.xL}</button></div>
    <ul>${rs.map(r => `<li class="${r.ok ? '' : 'bad'}">${r.ok ? '' : '✗ '}${esc(r.text)}</li>`).join('')}</ul>
    ${editable ? `<div class="mv">
      <div class="fld"><label>วัน</label><select class="inp" id="mvd">${L.DAYS.map((d, i) => `<option value="${i}" ${i === e.d ? 'selected' : ''}>${d}</option>`).join('')}</select></div>
      <div class="fld"><label>ช่วงเวลา</label><select class="inp" id="mvh"><option value="am" ${e.h === 'am' ? 'selected' : ''}>เช้า ${L.timeLabel(p.hours, 'am')}</option><option value="pm" ${e.h === 'pm' ? 'selected' : ''}>บ่าย ${L.timeLabel(p.hours, 'pm')}</option></select></div>
      <div class="fld"><label>ห้อง</label><select class="inp" id="mvr">${roomOpts}</select></div>
      <button class="btn" data-act="manualMove" data-id="${e.id}">ย้าย</button></div>
      <div class="row" style="margin-top:12px"><button class="btn ghost sm" data-act="toggleLock" data-id="${e.id}">${IC.lock} ${e.lock ? 'ปลดล็อกคาบนี้' : 'ล็อกคาบนี้ (จัดใหม่แล้วไม่ย้าย)'}</button><button class="btn ghost sm" data-act="pickIssue" data-id="entry:${e.id}">${IC.spark} ให้ AI หาตำแหน่งอื่น</button><button class="btn ghost sm" data-act="unplace" data-id="${e.id}">นำออกจากตาราง</button></div>` : ''}
  </div>`;
}
function currentIssue(A, ents) {
  const id = S.ui.selIssue;
  if (id && id.startsWith('entry:')) { const e = ents.find(x => x.id === id.slice(6)); if (e) return { id, tag: 'ย้ายคาบ', cat: 'manual', ids: [e.id], text: 'หาตำแหน่งอื่นให้ ' + L.maps(ctx()).C[e.c].code, sub: 'ตำแหน่งที่ไม่ชนและตรงเงื่อนไข' }; }
  return A.issues.find(i => i.id === id) || null;
}
function issuesPanel(A, c, ents, editable, t) {
  const issues = A.issues.slice().sort((a, b) => (a.cat === 'unplaced') - (b.cat === 'unplaced'));
  if (!S.ui.selIssue || !(currentIssue(A, ents))) { const fixable = editable && issues.find(i => L.suggestFixes(c, ents, i, 1).length); S.ui.selIssue = editable && issues[0] ? (fixable || issues[0]).id : null; }
  const cur = currentIssue(A, ents);
  const list = issues.length ? issues.map(i => `<button class="issue ${cur && cur.id === i.id ? 'on' : ''}" data-act="pickIssue" data-id="${esc(i.id)}"><span class="tag ${i.cat === 'unplaced' ? 'unp' : ''}">${i.tag}</span><span><p>${esc(i.text)}</p><small>${esc(i.sub)}</small></span></button>`).join('')
    : ((t.fixLog || []).length ? (t.fixLog || []).slice(0, 6).map(f => `<div class="issue fixed"><span class="chk">${IC.checkL}</span><span><p><b>${esc(f.tag)}</b> &nbsp;${esc(f.text)}</p></span></div>`).join('') : `<div class="issue fixed"><span class="chk">${IC.checkL}</span><span><p><b>ไม่พบปัญหา</b> ตารางพร้อมส่งแบบร่าง</p></span></div>`);
  let ai = '';
  if (cur && editable) {
    const opts = L.suggestFixes(c, ents, cur, 3);
    if (S.ui.selOpt >= opts.length) S.ui.selOpt = 0;
    let body;
    if (opts.length) body = opts.map((o, i) => `<label class="opt ${S.ui.selOpt === i ? 'on' : ''}"><input type="radio" name="fix" ${S.ui.selOpt === i ? 'checked' : ''} data-act="selOpt" data-i="${i}"><span><b>${esc(o.title)}${o.best ? ' (แนะนำ)' : ''}</b>
        ${o.facts.good.length ? `<div class="f">${esc(o.facts.good.join(' · '))}</div>` : ''}${o.facts.warn.length ? `<div class="w">${esc(o.facts.warn.join(' · '))}</div>` : ''}</span></label>`).join('')
        + `<button class="btn block" style="margin-top:12px;border-radius:2px" data-act="applyFix">ใช้ทางแก้นี้</button>`;
    else {
      const dg = L.diagnose(c, ents, cur) || { title: 'ไม่พบทางแก้', reasons: [], actions: [] };
      const msg = (dg.code ? dg.code + ': ' : '') + dg.title + (dg.reasons[0] ? ' · ' + dg.reasons[0] : '');
      body = `<div class="banner warn" style="margin:4px 0 10px;align-items:flex-start"><div class="grow"><b>ย้ายคาบแก้ปัญหานี้ไม่ได้</b>${esc(dg.title)}
        <ul style="margin:6px 0 0;padding-left:18px">${dg.reasons.map(r => `<li class="small">${esc(r)}</li>`).join('')}</ul></div></div>
        <p class="small" style="margin:0 0 8px;color:var(--navy)">สิ่งที่ทำได้:</p>
        <div style="display:flex;flex-direction:column;gap:8px">
        ${dg.actions.includes('notifyMek') ? `<button class="btn ghost sm" data-act="diagNotify" data-msg="${esc(msg)}">แจ้งพี่เมกให้ตรวจห้อง/อุปกรณ์/เงื่อนไขอาจารย์</button>` : ''}
        ${dg.actions.includes('editCourse') ? `<button class="btn ghost sm" data-act="modal" data-m="course" data-id="${dg.courseId}">แก้ไขรายวิชา (จำนวนนักศึกษา/ประเภทห้อง)</button>` : ''}
        ${dg.actions.includes('unlock') ? `<button class="btn ghost sm" data-act="diagUnlock" data-id="${dg.entryId}">ปลดล็อกคาบ</button>` : ''}
        ${dg.actions.includes('rerun') ? '<button class="btn ghost sm" data-act="startAuto">จัดตารางใหม่ทั้งหมด</button>' : ''}</div>`;
    }
    ai = `<div class="panel" style="margin-top:20px">
      <div class="issue" style="cursor:default"><span class="tag ${cur.cat === 'unplaced' ? 'unp' : ''}" style="${cur.cat === 'manual' ? 'background:var(--navy)' : ''}">${cur.tag}</span><span><p>${esc(cur.text)}</p><small>${esc(cur.sub)}</small></span></div>
      <h3 style="font-size:26px;margin:14px 0 8px;display:flex;align-items:center;gap:8px">AI เสนอการแก้ไขปัญหา</h3>
      ${body}
      <p class="foot-note">ระบบเสนอเฉพาะทางที่แก้ปัญหาได้จริงโดยไม่สร้างจุดชนใหม่ เรียงจากทางที่กระทบน้อยที่สุด</p></div>`;
  }
  return `<div class="panel"><h3>รายงานปัญหาที่พบ (${issues.length})</h3>${list}</div>${ai}`;
}

/* ---------------- Admin: เผยแพร่ ---------------- */
function publishView() {
  const st = status(); const t = D.term || {};
  const pub = st === 'published';
  let top = '';
  if (st === 'confirmed') top = `<div class="banner ok" style="padding:20px 26px"><div class="grow"><b style="font-size:18px">พร้อมเผยแพร่ตารางเรียน ภาค ${esc(termLabel())}</b><span>พี่เมกตรวจสอบและยืนยันทุกคาบแล้ว · เมื่อเผยแพร่ อาจารย์และนักศึกษาจะดูตารางได้ทันที</span></div><button class="btn lg" data-act="modal" data-m="publish">เผยแพร่ตาราง</button></div>`;
  else if (pub) top = `<div class="banner ok"><div class="grow"><b>เผยแพร่แล้วเมื่อ ${thDT(t.published.at)}</b><span class="small">หน้าตารางสาธารณะ: อาจารย์และนักศึกษาเปิดดูได้โดยไม่ต้องเข้าสู่ระบบ</span></div><button class="btn ghost sm" data-act="go" data-p="public">ดูหน้าตารางสาธารณะ ${IC.chevR}</button></div>`;
  else top = `<div class="banner warn"><div class="grow"><b>ยังเผยแพร่ไม่ได้</b><span class="small">${st === 'sent' ? 'รอพี่เมกตรวจสอบแบบร่าง (ขั้นที่ 4)' : st === 'returned' ? 'พี่เมกขอให้แก้ไขตารางก่อน' : 'ต้องจัดตาราง ส่งแบบร่าง และให้พี่เมกยืนยันก่อน'}</span></div><button class="btn sm" data-act="go" data-p="${st === 'sent' ? 'dashboard' : 'schedule'}">${st === 'sent' ? 'ไปแดชบอร์ด' : 'ไปหน้าจัดตาราง'} ${IC.chevR}</button></div>`;
  const sent = t.emailSent;
  return `<main class="page">
    <div class="ph"><div><h1>เผยแพร่ตาราง</h1><p>ตารางเรียน ภาคเรียนที่ ${esc(termLabel())}</p></div></div>
    ${top}
    ${stepper()}
    <div class="grid g2" style="margin-top:32px;gap:50px">
      <div class="pub ${pub ? '' : 'off'}">${IC.mail}<div style="flex:1"><h3>ส่ง Email แจ้งอาจารย์</h3><p>ส่งตารางสอนให้อาจารย์ในรูปแบบเอกสาร PDF ผ่านช่องทางอีเมล</p>
        ${sent ? `<p class="small" style="color:var(--ok)">✓ ส่งแล้ว${sent.real ? '' : ' (จำลอง)'} ${sent.to.length} ท่าน${sent.failed && sent.failed.length ? ' · ไม่สำเร็จ ' + sent.failed.length : ''} · ${thDT(sent.at)}</p>` : ''}
        <div class="row" style="justify-content:space-between"><button class="link small" data-act="modal" data-m="emailPreview">ดูตัวอย่างอีเมล</button><button class="pillbtn" data-act="modal" data-m="emailSend">${sent ? 'ส่งอีกครั้ง' : 'ส่งอีเมล'}</button></div></div></div>
      <div class="pub ${pub ? '' : 'off'}">${IC.file}<div style="flex:1"><h3>Export เอกสารสำหรับ New ACIS และเผยแพร่ต่อ</h3>
        <div class="row" style="gap:16px;margin-top:10px"><button class="pillbtn" data-act="exportPDF">PDF</button><button class="pillbtn" data-act="exportExcel">Excel</button></div>
        <p class="small muted" style="margin-top:8px">PDF: ตารางแยกชั้นปี · Excel: รายคาบสำหรับกรอก New ACIS</p></div></div>
    </div>
    ${!pub ? '<p class="small muted" style="margin-top:12px">ส่งอีเมลและ Export ได้หลังเผยแพร่ตาราง</p>' : ''}
    <div class="row" style="justify-content:flex-end;margin-top:30px"><button class="btn teal lg" data-act="go" data-p="dashboard">กลับหน้าแดชบอร์ด</button></div>
  </main>`;
}

/* ---------------- พี่เมก: เงื่อนไขการสอน ---------------- */
function mekCondView() {
  const tab = S.ui.mekTab;
  return `<main class="page">
    <div class="ph"><div><h1>เงื่อนไขการสอน</h1><p>ข้อมูลห้องเรียนและเงื่อนไขการสอนอาจารย์ ภาคเรียนที่ ${esc(termLabel())}</p></div><div class="actions">${termSelectMek()}</div></div>
    ${mekStatusBanner()}
    <div class="seg" style="margin-bottom:14px">${[['rooms', 'ห้องเรียน'], ['teachers', 'อาจารย์']].map(([k, l]) => `<button class="${tab === k ? 'on' : ''}" style="min-height:44px;font-size:17px;border-radius:4px;padding:0 10px" data-act="mekTab" data-v="${k}">${l}</button>`).join('')}</div>
    ${tab === 'rooms' ? mekRooms() : mekTeachers()}
  </main>`;
}
function termSelectMek() { return `<div class="row"><label class="muted small" for="tsel2">ภาคเรียน</label><select id="tsel2" class="inp" style="width:140px;min-height:38px" data-act-change="setTerm">${D.terms.map(t => `<option value="${t.id}" ${t.id === S.termId ? 'selected' : ''}>${t.label}</option>`).join('')}</select></div>`; }
function mekStatusBanner() {
  const st = status();
  if (st === 'sent') return `<div class="banner warn"><div class="grow"><b>มีแบบร่างตารางรอตรวจสอบ</b><span class="small">ฉบับที่ ${D.term.version} · ส่งเมื่อ ${thDT(D.term.sentAt)}</span></div><button class="btn sm" data-act="go" data-p="mek-check">ไปตรวจสอบตาราง ${IC.chevR}</button></div>`;
  if (['confirmed', 'published'].includes(st)) return `<div class="banner info"><div class="grow"><b>${st === 'published' ? 'ตารางเผยแพร่แล้ว' : 'ยืนยันตารางแล้ว'}</b><span class="small">ถ้าแก้ไขข้อมูลห้อง/อาจารย์ ระบบจะแจ้งเตือนเจ้าหน้าที่จัดตารางให้ตรวจผลกระทบ</span></div></div>`;
  return '';
}
function mekRooms() {
  const rooms = D.rooms; const courses = D.courses;
  const q = (S.ui.mekSearch || '').toLowerCase();
  const list = courses.filter(c => !q || (c.code + c.name).toLowerCase().includes(q));
  const f = S.ui.form && S.ui.form.kind === 'course' ? S.ui.form : null;
  if (!f && courses.length) selectCourseForm((courses.find(c => !c.saved) || courses[0]).id);
  const F = S.ui.form && S.ui.form.kind === 'course' ? S.ui.form : null;
  return `<div class="card" style="padding:0;border-radius:12px;overflow:hidden">
    <div class="row" style="justify-content:space-between;padding:20px 22px 12px"><h3 style="font-size:21px">รายละเอียดห้องเรียน</h3><button class="btn teal sm" data-act="modal" data-m="room">${IC.plus} เพิ่มห้อง</button></div>
    <table class="tbl navy"><thead><tr><th style="padding-left:56px">ห้อง</th><th>ประเภท</th><th>ความจุ (คน)</th><th>อุปกรณ์</th><th>สถานะ</th><th></th></tr></thead>
    <tbody>${rooms.map(r => `<tr data-act="modal" data-m="room" data-id="${r.id}"><td style="padding-left:56px;font-size:17px">${r.id}</td><td style="font-size:17px">${L.ROOM_TYPE_LABEL[r.type].replace('ห้อง', r.type === 'คอมพิวเตอร์' ? 'แล็บ' : '')}</td><td style="font-size:17px">${r.cap}</td><td style="font-size:17px">${esc(roomEquipText(r))}</td><td style="font-size:17px">${roomStatusText(r)}</td><td><button class="btn ghost sm" style="border-radius:4px;min-width:120px" data-act="modal" data-m="room" data-id="${r.id}">แก้ไข</button></td></tr>`).join('')}</tbody></table><div style="height:18px"></div></div>
  <div style="display:grid;grid-template-columns:347px minmax(0,1fr);gap:20px;margin-top:28px;align-items:start">
    <div class="panel" style="padding:24px 18px"><h3 style="font-size:21px;margin-bottom:6px">รายวิชาในภาคเรียน</h3>
      <div class="srch"><input placeholder="search" data-fid="mekSearch" data-act-input="mekSearch" value="${esc(S.ui.mekSearch || '')}">${IC.search}</div>
      ${courses.length ? list.map(c => `<button class="list-i ${F && F.id === c.id ? 'on' : ''}" data-act="pickCourse" data-id="${c.id}"><span>${esc(c.code)}</span><span class="st ${c.saved ? '' : 'no'}">${c.saved ? 'บันทึกข้อมูล' : 'ยังไม่บันทึกข้อมูล'}</span></button>`).join('') : '<p class="muted small">ยังไม่มีรายวิชา · รอเจ้าหน้าที่จัดตารางนำเข้ารายวิชาจากหลักสูตร</p>'}
    </div>
    <div class="panel" style="padding:30px 38px">${F ? courseCondForm(F) : '<p class="muted">เลือกรายวิชาทางซ้าย</p>'}</div>
  </div>`;
}
function selectCourseForm(id) {
  const c = D.courses.find(x => x.id === id); if (!c) { S.ui.form = null; return; }
  S.ui.form = { kind: 'course', id, year: c.year, students: c.students, note: c.note || '', parts: clone(c.parts) };
}
function courseCondForm(F) {
  const c = D.courses.find(x => x.id === F.id); if (!c) return '';
  const rooms = D.rooms;
  return `<h3 style="font-size:24px">เงื่อนไขการใช้ห้อง ${esc(c.code)} ${esc(c.name)}</h3>
    <p class="small muted" style="margin:4px 0 14px">${esc((D.teachers.find(t => t.id === c.teacher) || {}).name || '')}${c.saved ? '' : ' · ข้อมูลตั้งต้นจากหลักสูตร ยังไม่ได้ยืนยัน'}</p>
    ${F.parts.map((p, i) => `<div style="${F.parts.length > 1 ? 'border:1px solid var(--line);border-radius:12px;padding:14px 16px;margin-bottom:12px;background:rgba(255,255,255,.55)' : ''}">
      ${F.parts.length > 1 ? `<b style="color:var(--ink)">คาบ${esc(p.kind)} · ${p.hours} ชั่วโมง</b>` : ''}
      <div class="grid g2" style="gap:18px;margin-top:6px">
        <div class="fld"><label>ประเภทห้องที่ต้องการ</label><select class="inp" data-f="form.parts.${i}.type" data-rr="1">${L.ROOM_TYPES.map(t => `<option value="${t}" ${p.type === t ? 'selected' : ''}>${L.ROOM_TYPE_LABEL[t]}</option>`).join('')}</select></div>
        <div class="fld"><label>ห้องที่ต้องการ (ถ้ามี)</label><select class="inp" data-f="form.parts.${i}.room"><option value="">ไม่ระบุ · ให้ระบบเลือก</option>${rooms.filter(r => r.type === p.type).map(r => `<option value="${r.id}" ${p.room === r.id ? 'selected' : ''}>${r.id} (จุ ${r.cap})</option>`).join('')}</select></div>
      </div>
      <div class="lbl" style="margin-top:14px">อุปกรณ์ที่ต้องการใช้</div>
      <div>${L.EQUIP.map(eq => `<label class="chk"><input type="checkbox" data-farr="form.parts.${i}.equip" value="${eq.id}" ${(p.equip || []).includes(eq.id) ? 'checked' : ''}>${eq.label}</label>`).join('')}</div>
    </div>`).join('')}
    <div class="grid g2" style="gap:40px;margin-top:10px">
      <div class="fld"><label>ชั้นปีที่เรียน</label><select class="inp" data-f="form.year" data-num="1">${[1, 2, 3, 4].map(y => `<option value="${y}" ${F.year == y ? 'selected' : ''}>ปี ${y}</option>`).join('')}</select></div>
      <div class="fld"><label>จำนวนนักศึกษา</label><input class="inp" type="number" min="1" data-f="form.students" data-num="1" value="${F.students}"></div>
    </div>
    <div class="fld" style="margin-top:18px"><label>หมายเหตุ</label><textarea class="inp" data-f="form.note" placeholder="เช่น ขอห้องที่มีกระดานไวท์บอร์ดขนาดใหญ่">${esc(F.note)}</textarea></div>
    <div class="row" style="justify-content:flex-end;margin-top:14px"><button class="btn lg" style="border-radius:22px" data-act="saveCourseCond">บันทึกข้อมูล</button></div>`;
}
function mekTeachers() {
  const ts = D.teachers; const q = (S.ui.mekSearch || '').toLowerCase();
  if (!S.ui.form || S.ui.form.kind !== 'teacher') { const t = ts.find(x => !x.saved) || ts[0]; if (t) selectTeacherForm(t.id); }
  const F = S.ui.form && S.ui.form.kind === 'teacher' ? S.ui.form : null;
  const t = F && ts.find(x => x.id === F.id);
  const meet = D.globals;
  return `<div style="display:grid;grid-template-columns:347px minmax(0,1fr);gap:18px;align-items:start">
    <div class="panel" style="padding:24px 18px"><h3 style="font-size:21px;margin-bottom:6px">อาจารย์ภายในภาควิชา</h3>
      <div class="srch"><input placeholder="search" data-fid="mekSearch" data-act-input="mekSearch" value="${esc(S.ui.mekSearch || '')}">${IC.search}</div>
      ${ts.filter(x => !q || x.name.toLowerCase().includes(q)).map(x => `<button class="list-i ${F && F.id === x.id ? 'on' : ''}" data-act="pickTeacher" data-id="${x.id}"><span>${esc(x.name)}</span><span class="st ${x.saved ? '' : 'no'}">${x.saved ? 'บันทึกข้อมูล' : 'ยังไม่บันทึกข้อมูล'}</span></button>`).join('')}
      <button class="link small" style="margin:10px" data-act="addTeacher">+ เพิ่มอาจารย์</button></div>
    ${F && t ? `<div class="panel" style="padding:30px 38px">
      <h3 style="font-size:24px">เงื่อนไขการสอน ${esc(t.name)}</h3>
      <div class="lbl" style="margin-top:14px;font-size:17px">ช่วงเวลาที่สะดวกสอน (คลิกที่ช่องเพื่อเปลี่ยนสถานะ)</div>
      <div class="row" style="gap:6px;margin-bottom:6px"><span class="badge" style="border:1px solid var(--teal);color:var(--teal-d);font-weight:500">สะดวก</span><span class="badge" style="border:1px solid var(--red);color:var(--red);font-weight:500">ไม่สะดวก</span><span class="badge" style="border:1px dashed #B9C7CC;color:var(--muted);font-weight:500">เงื่อนไขส่วนกลาง</span></div>
      <div class="avail"><span></span>${L.DAYS_EN.map(d => `<span class="hd">${d}</span>`).join('')}
        ${L.HALVES.map(h => `<span class="rl"><b>${h === 'am' ? 'ช่วงเช้า' : 'ช่วงบ่าย'}</b><span>${h === 'am' ? '08:30 น. - 12:30 น.' : '13:30 น. - 17:30 น.'}</span></span>${[0, 1, 2, 3, 4].map(d => { const k = d + h; const g = meet.find(g => (g.slots || []).includes(k) && (!g.years || !g.years.length)); if (g) return `<button class="av lockd" title="${esc(g.title)}" disabled>${esc(g.title.slice(0, 10))}</button>`; const no = F.off.includes(k); return `<button class="av ${no ? 'no' : ''}" data-act="toggleOff" data-k="${k}">${no ? 'ไม่สะดวก' : 'สะดวก'}</button>`; }).join('')}`).join('')}
      </div>
      <div class="row" style="justify-content:space-between;margin-top:30px"><span class="lbl" style="font-size:17px;margin:0">เงื่อนไขในการสอน</span><button class="btn ghost sm" style="border-radius:4px" data-act="addCond">${IC.plus} เพิ่มเงื่อนไข</button></div>
      ${F.conds.map((cd, i) => `<div class="condrow"><input class="inp" style="border:0;padding:0;min-height:30px;font-size:17px;background:none" data-f="form.conds.${i}" value="${esc(cd)}" placeholder="พิมพ์เงื่อนไข เช่น ติดประชุมทุกวันอังคารบ่าย"><button class="x" aria-label="ลบ" data-act="delCond" data-i="${i}" style="color:var(--muted)">${IC.x}</button></div>`).join('') || '<p class="small muted">ยังไม่มีเงื่อนไขเพิ่มเติม</p>'}
      <div class="grid g3" style="margin-top:16px;gap:20px"><div class="fld"><label>ชื่ออาจารย์</label><input class="inp" data-f="form.name" value="${esc(F.name)}"></div><div class="fld"><label>อีเมล (ใช้ส่งตารางสอน)</label><input class="inp" data-f="form.email" value="${esc(F.email)}"></div><div class="fld"><label>ตำแหน่ง</label><input class="inp" data-f="form.title" value="${esc(F.title)}" placeholder="เช่น หัวหน้าภาค"></div></div>
      <div class="row" style="justify-content:flex-end;margin-top:20px"><button class="btn lg" style="border-radius:22px" data-act="saveTeacher">บันทึกข้อมูล</button></div>
    </div>` : '<div class="panel">เลือกอาจารย์</div>'}
  </div>`;
}
function selectTeacherForm(id) { const t = D.teachers.find(x => x.id === id); if (!t) return; S.ui.form = { kind: 'teacher', id, name: t.name, off: clone(t.off || []), conds: clone(t.conds || []), email: t.email || '', title: t.title || '' }; }

/* ---------------- พี่เมก: ตรวจสอบตาราง ---------------- */
function mekCheckView() {
  const st = status(); const t = D.term || {}; const c = ctx(); const ents = D.entries;
  const head = `<div class="ph"><div><h1>ตรวจสอบตาราง</h1><p>ตารางแบบร่าง จากเจ้าหน้าที่จัดตารางสอน ภาคเรียนที่ ${esc(termLabel())}</p></div><div class="actions">${termSelectMek()}</div></div>`;
  const ro = ['confirmed', 'published'].includes(st);
  if (st !== 'sent' && !ro) {
    const msg = {
      empty: ['ยังไม่มีแบบร่างส่งมา', 'เจ้าหน้าที่จัดตารางยังไม่ได้เริ่มจัดตารางภาคนี้ · ระหว่างนี้บันทึกข้อมูลห้องและเงื่อนไขอาจารย์ได้ที่เมนู "เงื่อนไขการสอน"'],
      prep: ['ยังไม่มีแบบร่างส่งมา', 'เจ้าหน้าที่จัดตารางกำลังเตรียมข้อมูล · ตรวจว่ารายวิชาทุกวิชาบันทึกเงื่อนไขห้องแล้ว'],
      draft: ['ยังไม่มีแบบร่างส่งมา', 'เจ้าหน้าที่จัดตารางกำลังจัดตาราง เมื่อส่งแบบร่างจะมีแจ้งเตือนที่กระดิ่ง'],
      returned: ['ส่งกลับให้แก้ไขแล้ว', 'รอแบบร่างฉบับใหม่จากเจ้าหน้าที่จัดตาราง'],
      confirmed: ['ยืนยันตารางแล้ว ✓', 'รอเจ้าหน้าที่จัดตารางเผยแพร่ตาราง'],
      published: ['ตารางเผยแพร่แล้ว ✓', 'ดูตารางฉบับเผยแพร่ได้ที่หน้าตารางสาธารณะ']
    }[st];
    return `<main class="page">${head}${stepper()}<div class="empty" style="margin-top:30px"><span style="color:var(--navy)">${IC.cal}</span><h3>${msg[0]}</h3><p class="muted">${msg[1]}</p>
      ${st === 'returned' ? `<div style="max-width:560px;margin:10px auto;text-align:left">${(t.returnNotes || []).map(n => `<div class="condrow" style="font-size:15px"><span><b>${esc(n.code)}</b> ${esc(n.note)}</span>${n.done ? '<span class="badge teal">แก้แล้ว</span>' : '<span class="badge grey">รอแก้</span>'}</div>`).join('')}</div>` : ''}
      ${st === 'published' ? '<button class="btn" data-act="go" data-p="public">ดูหน้าตารางสาธารณะ</button>' : st === 'confirmed' || st === 'returned' ? '' : '<button class="btn ghost" data-act="go" data-p="mek-conditions">ไปเงื่อนไขการสอน</button>'}</div></main>`;
  }
  const A = L.analyze(c, ents); const M = L.maps(c);
  const placed = A.placed.slice().sort((a, b) => a.d - b.d || (a.h > b.h ? 1 : -1) || a.id.localeCompare(b.id));
  const rv = t.review || {};
  const ck = {}; placed.forEach(e => ck[e.id] = L.checks(c, ents, e.id, A));
  const N = placed.length;
  const cnt = k => placed.filter(e => ck[e.id][k]).length;
  const cards = [['teacher', 'ตรงเงื่อนไขอาจารย์'], ['equip', 'อุปกรณ์พร้อม'], ['cap', 'ความจุพอ'], ['clash', 'ไม่ชน (ห้อง/อาจารย์/ชั้นปี)']];
  const filt = S.ui.rfilter;
  const rows = filt ? placed.filter(e => !ck[e.id][filt]) : placed;
  if (!S.ui.rsel || !placed.find(e => e.id === S.ui.rsel)) S.ui.rsel = (placed.find(e => !rv[e.id]) || placed[0] || {}).id;
  const sel = placed.find(e => e.id === S.ui.rsel);
  const fixN = placed.filter(e => (rv[e.id] || {}).s === 'fix').length;
  const doneN = placed.filter(e => rv[e.id]).length;
  const autoOk = placed.filter(e => !rv[e.id] && ck[e.id].all).length;
  const selRoom = sel && M.R[sel.r];
  const prevNotes = {}; (t.prevNotes || []).forEach(n => prevNotes[n.eid] = n);
  const mark = (ok, txt) => ok ? `<span class="ok-c">${IC.checkL}</span>` : `<span class="bad-c">${txt || IC.x}</span>`;
  let main;
  if (S.ui.rmode === 'table') {
    const v = vstate('chk', c); if (sel && v.mode === 'room' && !S.ui.rkeep) { v.key = sel.r; }
    main = viewCtrl('chk', c) + timeline({ ctx: c, entries: ents, v: vstate('chk', c), A, sel: ro ? null : S.ui.rsel, act: ro ? 'noop' : 'rpick', notes: Object.fromEntries(placed.filter(e => (rv[e.id] || {}).s === 'fix').map(e => [e.id, 1])) });
  } else {
    main = `<table class="tbl navy"><thead><tr><th>คาบ</th><th>ห้อง</th><th>เงื่อนไขอาจารย์</th><th>อุปกรณ์</th><th>ความจุ</th><th>ไม่มีความขัดแย้ง</th><th>การตรวจสอบ</th></tr></thead><tbody>
    ${rows.map(e => { const co = M.C[e.c]; const p = co.parts[e.p]; const k = ck[e.id]; const r = M.R[e.r]; const rvw = rv[e.id]; const [t0, t1] = L.partTime(p.hours, e.h);
      return `<tr class="${!ro && S.ui.rsel === e.id ? 'sel' : ''}" ${ro ? 'style="cursor:default"' : `data-act="rpick" data-eid="${e.id}"`}><td><b style="color:var(--navy);font-weight:600">${esc(co.code)}</b>${co.parts.length > 1 ? ' <span class="small muted">' + esc(p.kind) + '</span>' : ''}${prevNotes[e.id] ? ' <span class="badge amber">เคยขอแก้</span>' : ''}<br><span class="small" style="color:var(--navy)">${L.DAYS_SHORT[e.d]} ${L.fmtT(t0)}-${L.fmtT(t1)}</span></td><td>${e.r}</td><td>${mark(k.teacher)}</td><td>${mark(k.equip, 'ไม่พอ')}</td><td class="${k.cap ? '' : 'bad-c'}">${co.students}/${r ? r.cap : '-'}</td><td>${mark(k.clash)}</td>
      <td>${ro ? '<span class="ok-c small" style="font-weight:600">✓ ยืนยันแล้ว</span>' : rvw ? (rvw.s === 'pass' ? `<span class="ok-c">${IC.checkL}</span>` : '<span class="bad-c">รอการแก้ไข</span>') : (k.all ? '<span class="muted small">ยังไม่ตรวจ</span>' : '<span class="bad-c small">ระบบพบปัญหา</span>')}</td></tr>`; }).join('')}</tbody></table>
    ${filt ? `<p class="small" style="margin-top:8px">กรองเฉพาะคาบที่ไม่ผ่าน · <button class="link small" data-act="rfilter" data-v="">แสดงทั้งหมด</button></p>` : ''}`;
  }
  let side = '';
  if (sel && !ro) {
    const co = M.C[sel.c]; const p = co.parts[sel.p]; const k = ck[sel.id]; const rvw = rv[sel.id] || {}; const tch = M.T[co.teacher] || {};
    const fail = k.errors.map(x => x.text);
    side = `<div class="review-card"><div class="small muted">${esc(co.code)}${co.parts.length > 1 ? ' · คาบ' + esc(p.kind) : ''}</div><h3 style="font-size:20px">${esc(co.name)}</h3>
      <div class="small muted" style="color:var(--navy)">${co.credit ? esc(co.credit) + ' · ' : ''}${L.DAYS[sel.d]} ${L.timeLabel(p.hours, sel.h)} ${sel.r} ${esc(tch.name || '')}</div>
      <ul class="cl">${[['teacher', 'เงื่อนไขอาจารย์'], ['equip', 'อุปกรณ์'], ['cap', 'ความจุ ' + co.students + '/' + ((M.R[sel.r] || {}).cap || '-')], ['clash', 'ไม่ชนกัน']].map(([kk, l]) => `<li>${k[kk] ? `<span class="ic-ok">${IC.check}</span>` : `<span class="ic-bad">${IC.x}</span>`}${l}</li>`).join('')}</ul>
      ${fail.length ? `<div class="small bad-c" style="margin-bottom:6px">${fail.map(esc).join('<br>')}</div>` : ''}
      ${prevNotes[sel.id] ? `<div class="small" style="background:var(--amber-bg);padding:6px 10px;border-radius:8px;margin-bottom:6px">รอบก่อนขอแก้: ${esc(prevNotes[sel.id].note)}</div>` : ''}
      <h3 style="font-size:19px;margin-top:10px">ต้องแก้ไขวิชานี้หรือไม่</h3>
      <div class="yn"><button class="${rvw.s === 'pass' ? 'on' : ''}" data-act="review" data-s="pass">ผ่าน</button><button class="${rvw.s === 'fix' ? 'on fix' : ''}" data-act="review" data-s="fix">ต้องแก้ไข</button></div>
      ${rvw.s === 'fix' ? `<div class="lbl" style="font-size:18px;font-weight:700">หมายเหตุ</div><textarea class="inp" style="border-radius:8px;font-size:13px" data-fid="rnote-${sel.id}" data-act-input="rnote" placeholder="เช่น ควรย้ายวิชานี้ไปเรียนห้องบรรยายแทน">${esc(S.ui.noteDraft && S.ui.noteDraft[sel.id] != null ? S.ui.noteDraft[sel.id] : rvw.note || '')}</textarea>` : ''}
      <div class="row" style="justify-content:flex-end;margin-top:12px"><button class="btn ghost" style="border-color:var(--teal);font-size:17px" data-act="rnext">วิชาถัดไป ${IC.arrow}</button></div></div>`;
  }
  const remaining = N - doneN;
  let cta;
  if (ro) {
    side = `<div class="review-card" style="text-align:center;padding:26px 20px"><div class="success"><div class="ic">${IC.checkL}</div></div><h3 style="font-size:21px">ยืนยันตารางแล้ว</h3><p class="small muted" style="margin:6px 0 0">${t.confirmedAt ? 'เมื่อ ' + thDT(t.confirmedAt) + ' · ' : ''}ผ่านการตรวจ ${N}/${N} คาบ</p><p class="small" style="color:var(--navy);margin:10px 0 0">${st === 'published' ? 'เจ้าหน้าที่จัดตารางเผยแพร่ตารางแล้ว' : 'รอเจ้าหน้าที่จัดตารางเผยแพร่ตาราง'}</p>${st === 'published' ? '<button class="btn block" style="margin-top:14px" data-act="go" data-p="public">ดูหน้าตารางสาธารณะ</button>' : ''}</div>`;
    cta = '<p class="foot-note" style="text-align:center">ถ้าข้อมูลห้องเปลี่ยน ให้แก้ที่เมนู "เงื่อนไขการสอน" ระบบจะแจ้งเจ้าหน้าที่จัดตารางให้</p>';
  } else if (!remaining && !fixN && !S.ui.reviewEdit) {
    side = `<div class="review-card" style="text-align:center;padding:26px 20px"><div class="success"><div class="ic">${IC.checkL}</div></div><h3 style="font-size:21px">ตรวจครบแล้ว · ผ่านทั้งหมด ${N} คาบ</h3><p class="small muted" style="margin:6px 0 0">กดยืนยันเพื่อแจ้งเจ้าหน้าที่จัดตารางว่าตารางพร้อมเผยแพร่</p><button class="link small" style="margin-top:10px" data-act="reviewEdit">แก้ไขผลการตรวจรายวิชา</button></div>`;
    cta = `<button class="btn block lg" style="margin-top:20px" data-act="modal" data-m="confirmDraft">ยืนยันตารางทั้งหมด</button>`;
  } else if (fixN) cta = `<button class="btn block lg red" style="margin-top:20px" data-act="modal" data-m="returnDraft">ส่งกลับให้แก้ไข (${fixN} คาบ)</button>`;
  else if (remaining) cta = `<button class="btn block lg" style="margin-top:20px" disabled>ยืนยันตารางทั้งหมด</button><p class="foot-note" style="text-align:center">ตรวจอีก ${remaining} คาบ จึงยืนยันได้</p>${autoOk ? `<button class="btn ghost block sm" data-act="passAuto">ผ่านทุกคาบที่ระบบไม่พบปัญหา (${autoOk} คาบ)</button>` : ''}`;
  else cta = `<button class="btn block lg" style="margin-top:20px" data-act="modal" data-m="confirmDraft">ยืนยันตารางทั้งหมด</button>`;
  return `<main class="page">${head}
    ${ro ? `<div class="banner ok"><div class="grow"><b>ยืนยันตารางทั้งหมดแล้ว</b><span class="small">${st === 'published' ? 'ตารางเผยแพร่แล้ว' : 'รอเผยแพร่'} · หน้านี้แสดงผลการตรวจแบบดูอย่างเดียว</span></div></div>` : ''}
    <div style="font-size:22px;font-weight:700;color:var(--ink);margin:-8px 0 18px">ระบบตรวจให้แล้ว 4 เรื่อง</div>
    ${t.sentMsg ? `<div class="banner info"><div class="grow"><b>ข้อความจากเจ้าหน้าที่จัดตาราง</b>${esc(t.sentMsg)}</div></div>` : ''}
    <div class="grid g4">${cards.map(([k, l]) => { const n = cnt(k); const bad = N - n; return `<div class="stat click ${filt === k ? 'sel' : ''}" style="padding:14px 16px" data-act="rfilter" data-v="${bad ? k : ''}"><div class="row" style="justify-content:space-between"><b style="font-size:15px;color:var(--ink)">${l}</b>${bad ? `<span class="badge warn">${IC.warn} ${bad}</span>` : `<span class="badge ok">${IC.check} ผ่าน</span>`}</div><div style="font-size:38px;font-weight:600;color:var(--ink)">${n} / ${N} คาบ</div><div class="small muted">${bad ? 'กดเพื่อดู ' + bad + ' คาบที่ไม่ผ่าน' : 'ไม่พบปัญหา'}</div></div>`; }).join('')}</div>
    <div class="row" style="margin:24px 0 6px;gap:18px"><b style="font-size:24px;color:var(--ink)">ตารางเรียน</b><div class="tabsx"><button class="${S.ui.rmode === 'table' ? 'on' : ''}" data-act="rmode" data-v="table">ตาราง</button><button class="${S.ui.rmode === 'list' ? 'on' : ''}" data-act="rmode" data-v="list">รายการ</button></div><span class="muted small">${ro ? 'ยืนยันแล้ว ' + N + '/' + N + ' คาบ' : 'ตรวจแล้ว ' + doneN + '/' + N + ' คาบ'}</span></div>
    <p class="muted" style="margin:0 0 14px">${selRoom ? `กำลังดู: ห้อง ${selRoom.id} | ${L.ROOM_TYPE_LABEL[selRoom.type]}${selRoom.mac ? ' Mac' : selRoom.win ? ' Windows' : ''} จุ ${selRoom.cap} คน` : ''}</p>
    <div style="display:grid;grid-template-columns:minmax(0,1fr) 380px;gap:38px;align-items:start">
      <div>${main}</div><div style="position:sticky;top:90px">${side}${cta}</div></div>
  </main>`;
}

/* ---------------- ตารางสาธารณะ ---------------- */
function publicView() {
  const P = S.ui.pub;
  const pubTerms = D.terms.filter(t => P[t.id] && P[t.id].published);
  if (!P._loaded) { loadPublic(); }
  const id = P.sel && pubTerms.find(t => t.id === P.sel) ? P.sel : (pubTerms[pubTerms.length - 1] || {}).id;
  const T = id && P[id]; const snap = T && T.published;
  let body;
  if (!P._loaded) body = '<p class="muted"><span class="spin"></span> กำลังโหลด…</p>';
  else if (!snap) body = '<div class="empty"><h3>ยังไม่มีตารางที่เผยแพร่</h3></div>';
  else {
    const c = { rooms: (snap.rooms || []).map(r => Object.assign({ mac: 0, win: 0, broken: 0, status: 'ready' }, D.rooms.find(x => x.id === r.id) || {}, r)), teachers: snap.teachers || [], globals: D.globals, courses: snap.courses || [] };
    body = `<div class="row" style="justify-content:space-between;margin-bottom:16px"><div class="row"><label class="muted" for="psel">ภาคเรียน</label><select id="psel" class="inp" style="width:140px" data-act-change="pubSel">${pubTerms.map(t => `<option value="${t.id}" ${t.id === id ? 'selected' : ''}>${t.label}</option>`).join('')}</select></div><span class="muted small">เผยแพร่เมื่อ ${thDT(snap.at)}</span></div>`
      + viewCtrl('pub', c) + timeline({ ctx: c, entries: snap.entries || [], v: vstate('pub', c), A: null, act: 'noop' });
  }
  return `<header class="topbar"><div class="logo" data-act="go" data-p="public">CMMschedule</div><nav class="nav"><button class="on">ตารางเรียน</button></nav><div class="tb-right"><button class="btn ghost" data-act="go" data-p="${S.session ? PAGES[S.session.role][0] : 'login'}">${S.session ? 'กลับเข้าระบบ' : 'เข้าสู่ระบบ'}</button></div></header>
    <main class="page"><div class="ph"><div><h1>ตารางเรียนหลักสูตร CMM</h1><p>สำหรับอาจารย์และนักศึกษา · ดูได้โดยไม่ต้องเข้าสู่ระบบ</p></div></div>${body}</main>`;
}
async function loadPublic() {
  const P = S.ui.pub; if (P._loading) return; P._loading = true;
  for (const t of D.terms) { const d = (await Store.getOnce('public/' + t.id)) || (await Store.getOnce('terms/' + t.id)); if (d) P[t.id] = d; }
  P._loaded = true; P._loading = false; scheduleRender();
}

function toastsView() {
  return `<div class="toasts">${S.ui.toasts.map(t => `<div class="toast ${t.kind === 'bad' ? 'bad' : ''}">${esc(t.text)}${t.action ? `<button data-act="${t.action.act}">${esc(t.action.label)}</button>` : ''}</div>`).join('')}</div>`;
}

/* CMMschedule — modals, actions, drag & drop movement, exports, init */
// Old versions copied the broken-machine count into the note ("เสีย 2 เครื่อง"). That text is cleared when the
// room is opened; if someone types it into the note themselves, it is read as the broken-machine count.
const autoNote = n => /^\s*เสีย\s*\d+\s*เครื่อง\s*$/.test(String(n || ''));

/* ---------------- modals ---------------- */
function openModal(type, id, extra) {
  const m = { type, f: {}, err: '' };
  const c = D.courses; const tch = D.teachers;
  if (type === 'import') Object.assign(m, { rows: null, file: '' });
  if (type === 'course') { const co = c.find(x => x.id === id); m.f = co ? clone(co) : { id: '', code: 'CMM ', name: '', year: 1, students: 40, teacher: (tch[0] || {}).id, elective: false, parts: [{ kind: 'บรรยาย', type: 'บรรยาย', hours: 3, equip: ['projector'], room: '' }], isNew: true }; }
  if (type === 'global') { const g = D.globals.find(x => x.id === id); m.f = g ? clone(g) : { id: '', title: '', kind: 'meeting', slots: [], years: [], note: '', isNew: true }; }
  if (type === 'room') { const r = D.rooms.find(x => x.id === id); m.f = r ? clone(r) : { id: '', type: 'บรรยาย', cap: 40, mac: 0, win: 0, broken: 0, projector: true, mic: false, status: 'ready', closedUntil: '', note: '', isNew: true }; m.f.hasMac = !!m.f.mac; m.f.hasWin = !!m.f.win; if (autoNote(m.f.note)) m.f.note = ''; }
  if (type === 'newTerm') m.f = { sem: 1, year: 2570, start: '2027-06-08' };
  if (type === 'send') m.f = { msg: '' };
  if (type === 'emailPreview' || type === 'emailSend') { const ids = teachersWithSessions(); m.f = { tid: ids[0], sel: ids.filter(i => (tch.find(t => t.id === i) || {}).email) }; }
  Object.assign(m, extra || {});
  S.ui.modal = m; S.ui.drop = null; scheduleRender();
}
function closeModal() { S.ui.modal = null; scheduleRender(); }
function teachersWithSessions() { const ents = (status() === 'published' && D.term.published) ? D.term.published.entries : D.entries.filter(e => e.d != null); const M = L.maps(ctx()); const s = new Set(); ents.forEach(e => { const c = M.C[e.c]; if (c) s.add(c.teacher); }); return D.teachers.filter(t => s.has(t.id)).map(t => t.id); }

function modalView() {
  const m = S.ui.modal; if (!m) return '';
  const f = m.f; let h = '', size = '';
  const errP = m.err ? `<p class="err-msg" style="margin:8px 0 0">${esc(m.err)}</p>` : '';
  const ft = (ok, label, extra) => `<div class="ft">${extra || ''}<button class="btn ghost-t" style="min-width:140px;border-radius:10px" data-act="closeModal">ยกเลิก</button><button class="btn teal" style="min-width:150px;border-radius:10px" data-act="${ok}">${label}</button></div>`;
  switch (m.type) {
    case 'import': {
      size = 'lg';
      h = `<h2 class="nb">นำเข้าข้อมูลรายวิชา</h2><p class="muted" style="margin:6px 0 16px">นำเข้าข้อมูลจากไฟล์ Excel จากเล่มหลักสูตร (.xlsx หรือ .csv)</p>
        ${m.rows ? `<div class="banner info" style="margin-bottom:10px"><div class="grow"><b>${esc(m.file)}</b>พบ ${m.rows.length} รายวิชา${m.newT && m.newT.length ? ' · อาจารย์ใหม่ ' + m.newT.length + ' ท่าน' : ''}</div><button class="link small" data-act="importReset">เลือกไฟล์ใหม่</button></div>
          <div style="max-height:300px;overflow:auto;border:1px solid var(--line);border-radius:8px"><table class="tbl lined"><thead><tr><th>รหัสวิชา</th><th>ชื่อวิชา</th><th>หน่วยกิต</th><th>ปี</th><th>นศ.</th><th>อาจารย์</th><th>รูปแบบ</th><th>สถานะ</th></tr></thead><tbody>
          ${m.rows.map(r => { const ex = D.courses.find(c => c.id === r.id); return `<tr><td>${esc(r.code)}</td><td>${esc(r.name)}</td><td>${esc(r.credit || '-')}</td><td>${r.year}</td><td>${r.students}</td><td>${esc(r.teacherName)}</td><td>${r.parts.map(p => p.type + ' ' + p.hours + ' ชม.').join(' + ')}</td><td>${ex ? '<span class="badge grey">มีแล้ว</span>' : '<span class="badge teal">ใหม่</span>'}</td></tr>`; }).join('')}</tbody></table></div>`
        : `<label class="upload" id="dropzone" for="impFile">${IC.upload}<span>คลิกเพื่ออัปโหลดไฟล์</span><span class="small muted" style="font-weight:400">หรือลากไฟล์มาวาง · คอลัมน์: รหัสวิชา, ชื่อวิชา, ชั้นปี, จำนวนนักศึกษา, อาจารย์ผู้สอน, รูปแบบ, ชั่วโมง</span></label>
          <input type="file" id="impFile" accept=".xlsx,.xls,.csv" class="hide" data-act-change="importFile">
          <div class="row" style="margin-top:12px;justify-content:space-between"><button class="link small" data-act="importSample">ไม่มีไฟล์? ใช้ไฟล์หลักสูตรตัวอย่าง ภาค 2/2569</button>${S.dl || true ? '<button class="link small" data-act="tmplDownload">ดาวน์โหลดไฟล์แม่แบบ (.xlsx)</button>' : ''}</div>`}
        ${m.loading ? '<p class="muted small"><span class="spin"></span> กำลังอ่านไฟล์…</p>' : ''}${errP}
        ${ft(m.rows ? 'importSave' : 'noop', 'บันทึก')}`;
      break;
    }
    case 'importDone':
      h = `<div class="success"><div class="ic">${IC.checkL}</div><h2 class="nb">นำเข้าข้อมูลแล้ว ${m.n} วิชา</h2><p class="muted">${m.prev ? 'ใช้เงื่อนไขห้องเดิมจากภาคก่อน ' + m.prev + ' วิชา · ' : ''}${m.miss ? 'รอพี่เมกบันทึกเงื่อนไขห้อง ' + m.miss + ' วิชา (ระบบแจ้งเตือนพี่เมกแล้ว)' : 'ข้อมูลครบ'}</p><div class="row" style="justify-content:center;margin-top:14px"><button class="btn ghost" data-act="closeModal">ปิด</button><button class="btn" data-act="goClose" data-p="conditions">ไปหน้าเงื่อนไขห้องเรียน</button></div></div>`; size = 'sm'; break;
    case 'course': {
      h = `<h2>${f.isNew ? 'เพิ่มรายวิชา' : 'แก้ไขรายวิชา ' + esc(f.code)}</h2>
        <div class="grid g2" style="gap:14px"><div class="fld"><label>รหัสวิชา</label><input class="inp sq" data-f="m.code" value="${esc(f.code)}" ${f.isNew ? '' : 'readonly'}></div><div class="fld"><label>ชื่อวิชา</label><input class="inp sq" data-f="m.name" value="${esc(f.name)}"></div>
        <div class="fld"><label>หน่วยกิต (เช่น 3(2-2-6))</label><input class="inp sq" data-f="m.credit" value="${esc(f.credit || '')}" placeholder="3(2-2-6)"></div><div class="fld"><label>&nbsp;</label><span class="small muted">บรรยาย + ปฏิบัติ = ชั่วโมงต่อสัปดาห์ (3 หรือ 4 ชม.)</span></div>
        <div class="fld"><label>ชั้นปี</label><select class="inp sq" data-f="m.year" data-num="1">${[1, 2, 3, 4].map(y => `<option ${f.year == y ? 'selected' : ''} value="${y}">ปี ${y}</option>`).join('')}</select></div><div class="fld"><label>จำนวนนักศึกษา</label><input class="inp sq" type="number" data-f="m.students" value="${f.students}"></div>
        <div class="fld"><label>อาจารย์ผู้สอน</label><select class="inp sq" data-f="m.teacher">${D.teachers.map(t => `<option value="${t.id}" ${f.teacher === t.id ? 'selected' : ''}>${esc(t.name)}</option>`).join('')}</select></div><div class="fld"><label>&nbsp;</label><label class="chk"><input type="checkbox" data-f="m.elective" ${f.elective ? 'checked' : ''}>วิชาเลือก (ชนเวลากับวิชาอื่นของชั้นปีได้)</label></div></div>
        <div class="lbl" style="margin-top:14px">คาบเรียนต่อสัปดาห์</div>
        ${f.parts.map((p, i) => `<div class="row" style="margin-bottom:8px"><select class="inp sq" style="width:120px" data-f="m.parts.${i}.kind"><option ${p.kind === 'บรรยาย' ? 'selected' : ''}>บรรยาย</option><option ${p.kind === 'ปฏิบัติ' ? 'selected' : ''}>ปฏิบัติ</option></select><select class="inp sq" style="width:170px" data-f="m.parts.${i}.type">${L.ROOM_TYPES.map(t => `<option value="${t}" ${p.type === t ? 'selected' : ''}>${L.ROOM_TYPE_LABEL[t]}</option>`).join('')}</select><select class="inp sq" style="width:150px" data-f="m.parts.${i}.hours" data-num="1"><option value="3" ${p.hours == 3 ? 'selected' : ''}>3 ชั่วโมง</option><option value="4" ${p.hours == 4 ? 'selected' : ''}>4 ชั่วโมง</option></select>${f.parts.length > 1 ? `<button class="x" data-act="partDel" data-i="${i}" aria-label="ลบคาบ">${IC.x}</button>` : ''}</div>`).join('')}
        ${f.parts.length < 3 ? '<button class="link small" data-act="partAdd">+ เพิ่มคาบ</button>' : ''}
        <p class="small muted">อุปกรณ์และห้องที่ต้องการ พี่เมกเป็นผู้บันทึกในเมนู "เงื่อนไขการสอน"</p>${errP}
        ${ft('courseSave', 'บันทึก', f.isNew ? '' : '<button class="btn ghost sm" style="margin-right:auto;color:var(--red);border-color:var(--red)" data-act="courseDel">ลบรายวิชา</button>')}`;
      break;
    }
    case 'global': {
      h = `<h2>${f.isNew ? 'เพิ่มเงื่อนไขส่วนกลาง' : 'แก้ไขเงื่อนไขส่วนกลาง'}</h2>
        <div class="fld"><label>ชื่อเงื่อนไข</label><input class="inp sq" data-f="m.title" value="${esc(f.title)}" placeholder="เช่น ประชุมภาควิชา, วิชาศึกษาทั่วไป"></div>
        <div class="lbl" style="margin-top:14px">ช่วงเวลาที่ห้ามจัดคาบเรียน</div>
        <div class="avail" style="grid-template-columns:110px repeat(5,minmax(0,1fr));gap:8px"><span></span>${L.DAYS_EN.map(d => `<span class="hd small">${d}</span>`).join('')}
        ${L.HALVES.map(hf => `<span class="small">${hf === 'am' ? 'ช่วงเช้า' : 'ช่วงบ่าย'}</span>${[0, 1, 2, 3, 4].map(d => { const k = d + hf; const on = f.slots.includes(k); return `<button class="av ${on ? 'no' : ''}" style="height:36px;font-size:13px" data-act="gSlot" data-k="${k}">${on ? 'ห้ามจัด' : '–'}</button>`; }).join('')}`).join('')}</div>
        <div class="lbl" style="margin-top:14px">มีผลกับชั้นปี (ไม่เลือก = ทุกชั้นปี)</div>
        <div>${[1, 2, 3, 4].map(y => `<label class="chk"><input type="checkbox" data-act="gYear" data-y="${y}" ${f.years.includes(y) ? 'checked' : ''}>ปี ${y}</label>`).join('')}</div>
        <div class="fld" style="margin-top:10px"><label>หมายเหตุ</label><input class="inp sq" data-f="m.note" value="${esc(f.note)}"></div>${errP}
        ${ft('globalSave', 'บันทึก', f.isNew ? '' : '<button class="btn ghost sm" style="margin-right:auto;color:var(--red);border-color:var(--red)" data-act="globalDel">ลบ</button>')}`;
      break;
    }
    case 'room': {
      size = 'sm';
      h = `<h2>${f.isNew ? 'เพิ่มห้องเรียน' : 'แก้ไขห้องเรียน'}</h2>
        <div class="fld"><label>รหัสห้อง</label><input class="inp sq" data-f="m.id" value="${esc(f.id)}" placeholder="เช่น CB30603" ${f.isNew ? '' : 'readonly'}></div>
        <div class="grid g2" style="gap:12px;margin-top:10px"><div class="fld"><label>ประเภทห้อง</label><select class="inp sq" data-f="m.type">${L.ROOM_TYPES.map(t => `<option value="${t}" ${f.type === t ? 'selected' : ''}>${L.ROOM_TYPE_LABEL[t]}</option>`).join('')}</select></div><div class="fld"><label>ความจุ (คน)</label><input class="inp sq" type="number" min="1" data-f="m.cap" value="${f.cap}"></div></div>
        <div class="lbl" style="margin-top:14px">อุปกรณ์ในห้อง</div>
        <div class="row" style="gap:6px"><label class="chk" style="margin-right:4px"><input type="checkbox" data-f="m.hasMac" data-rr="1" ${f.hasMac ? 'checked' : ''}>คอมพิวเตอร์ Mac</label>${f.hasMac ? `<input class="inp sq" type="number" style="width:90px;min-height:32px" data-f="m.mac" value="${f.mac}"> เครื่อง` : ''}</div>
        <div class="row" style="gap:6px"><label class="chk" style="margin-right:4px"><input type="checkbox" data-f="m.hasWin" data-rr="1" ${f.hasWin ? 'checked' : ''}>คอมพิวเตอร์ Windows</label>${f.hasWin ? `<input class="inp sq" type="number" style="width:90px;min-height:32px" data-f="m.win" value="${f.win}"> เครื่อง` : ''}</div>
        <label class="chk"><input type="checkbox" data-f="m.projector" ${f.projector ? 'checked' : ''}>โปรเจกเตอร์</label><label class="chk"><input type="checkbox" data-f="m.mic" ${f.mic ? 'checked' : ''}>ไมค์</label>
        <div class="lbl" style="margin-top:14px">สถานะห้องเรียน</div>
        <div class="row"><label class="chk"><input type="radio" name="rst" value="ready" data-f="m.status" data-rr="1" ${f.status !== 'closed' ? 'checked' : ''}>พร้อมใช้งาน</label><label class="chk"><input type="radio" name="rst" value="closed" data-f="m.status" data-rr="1" ${f.status === 'closed' ? 'checked' : ''}>งดใช้</label>${f.status === 'closed' ? `<input class="inp sq" type="date" style="width:170px;min-height:32px" data-f="m.closedUntil" value="${esc(f.closedUntil || '')}" aria-label="งดใช้ถึงวันที่">` : ''}</div>
        ${f.hasMac || f.hasWin ? `<div class="row" style="gap:6px;margin-top:8px"><span>เครื่องที่เสีย (ใช้งานไม่ได้)</span><input class="inp sq" type="number" min="0" style="width:90px;min-height:32px" data-f="m.broken" value="${f.broken || 0}"><span>เครื่อง</span></div>
        <p class="small muted" style="margin:4px 0 0">ช่อง "สถานะ" ในตารางห้องแสดงตามจำนวนนี้ · ซ่อมเสร็จแล้วให้ใส่ 0</p>` : ''}
        <div class="fld" style="margin-top:10px"><label>หมายเหตุ</label><input class="inp sq" data-f="m.note" value="${esc(f.note || '')}" placeholder="ข้อความเพิ่มเติม (ไม่มีผลกับสถานะ)"></div>${errP}
        ${ft('roomSave', f.isNew ? 'บันทึกห้อง' : 'บันทึกการแก้ไข', f.isNew ? '' : '<button class="btn ghost sm" style="margin-right:auto;color:var(--red);border-color:var(--red)" data-act="roomDel">ลบห้อง</button>')}`;
      break;
    }
    case 'saved':
      size = 'sm'; h = `<div class="success"><div class="ic">${IC.checkL}</div><h2 class="nb" style="margin-bottom:6px">${esc(m.title || 'บันทึกข้อมูลแล้ว')}</h2>${m.text ? `<p class="muted">${esc(m.text)}</p>` : ''}<button class="btn teal" style="min-width:76px;margin-top:10px" data-act="${m.next ? 'goClose' : 'closeModal'}" ${m.next ? `data-p="${m.next}"` : ''}>${esc(m.btn || 'ปิด')}</button></div>`; break;
    case 'newTerm':
      size = 'sm'; h = `<h2>สร้างภาคเรียนใหม่</h2><div class="grid g2" style="gap:12px"><div class="fld"><label>ภาคเรียนที่</label><select class="inp sq" data-f="m.sem" data-num="1">${[1, 2, 3].map(x => `<option ${f.sem == x ? 'selected' : ''} value="${x}">${x}</option>`).join('')}</select></div><div class="fld"><label>ปีการศึกษา</label><input class="inp sq" type="number" data-f="m.year" value="${f.year}"></div></div>
        <div class="fld" style="margin-top:10px"><label>วันเปิดภาคเรียน</label><input class="inp sq" type="date" data-f="m.start" value="${f.start}"></div>${errP}${ft('newTermSave', 'สร้าง')}`; break;
    case 'missing':
      size = 'sm'; h = `<h2>ข้อมูลยังไม่ครบ</h2><p>ยังมี <b>${m.miss} วิชา</b> ที่พี่เมกยังไม่ได้บันทึกเงื่อนไขห้อง ระบบจะใช้ค่าตั้งต้นจากหลักสูตรแทน</p>${m.placed ? '<p class="small muted">ระบบจะจัดใหม่ทั้งหมด (คาบที่ล็อกไว้จะอยู่ที่เดิม)</p>' : ''}${ft('runAuto', 'จัดตารางต่อ')}`; break;
    case 'rerun':
      size = 'sm'; h = `<h2>จัดตารางใหม่ทั้งหมด?</h2><p>ระบบจะจัดใหม่จากเงื่อนไขล่าสุด การย้ายคาบเองในฉบับนี้จะหาย ยกเว้นคาบที่ล็อกไว้ (${D.entries.filter(e => e.lock).length} คาบ) · กด "ย้อนกลับ" ได้ภายหลัง</p>${ft('runAuto', 'เริ่มจัดตาราง')}`; break;
    case 'auto': {
      size = 'sm';
      const steps = m.steps || [];
      h = `<h2 class="nb">${m.res ? 'จัดตารางเสร็จแล้ว' : 'กำลังจัดตาราง…'}</h2>
        <div class="pbar"><i style="width:${Math.min(100, Math.round(m.step / steps.length * 100))}%"></i></div>
        <ul class="prog">${steps.map((s, i) => `<li class="${i < m.step ? 'done' : i === m.step ? 'now' : ''}">${i < m.step ? '✓' : i === m.step ? '<span class="spin"></span>' : '○'} ${esc(s)}</li>`).join('')}</ul>
        ${m.res ? `<div class="banner ${m.res.conflicts || m.res.unplacedCourses ? 'warn' : 'ok'}" style="margin:14px 0 0"><div class="grow"><b>ลงตาราง ${m.res.courseDone}/${m.res.courses} วิชา · พบจุดชน ${m.res.conflicts} จุด</b>ตรงตามเงื่อนไข ${m.res.okPct}%</div></div><div class="ft"><button class="btn" data-act="closeModal">ดูตาราง</button></div>` : ''}`;
      break;
    }
    case 'send': {
      const A = L.analyze(ctx(), D.entries);
      h = `<h2>ส่งแบบร่างให้พี่เมกตรวจ</h2><div class="kv"><b>ภาคเรียน</b><span>${esc(termLabel())} · ฉบับที่ ${(D.term.version || 0) + 1}</span><b>รายวิชา</b><span>${A.stats.courses} วิชา (${A.stats.sessions} คาบ)</span><b>จุดชน</b><span style="color:var(--ok)">0 จุด ✓</span><b>ตรงเงื่อนไข</b><span>${A.stats.okPct}%</span></div>
        <div class="fld" style="margin-top:16px"><label>ข้อความถึงพี่เมก (ถ้ามี)</label><textarea class="inp" data-f="m.msg" placeholder="เช่น ฝากเช็กเครื่องในห้อง CB30603 ให้หน่อยค่ะ">${esc(f.msg)}</textarea></div>
        <p class="small muted">ระหว่างรอตรวจ ตารางจะถูกล็อกไม่ให้แก้ไข</p>${ft('sendDraft', 'ส่งแบบร่าง')}`; break;
    }
    case 'reopen':
      size = 'sm'; h = `<h2>${status() === 'published' ? 'เริ่มแก้ไขรอบใหม่?' : 'แก้ไขตารางอีกครั้ง?'}</h2><p>สถานะจะกลับเป็น "จัดตาราง" ต้องส่งแบบร่างให้พี่เมกตรวจใหม่${status() === 'published' ? ' · ตารางที่เผยแพร่ไว้ยังแสดงอยู่จนกว่าจะเผยแพร่ฉบับใหม่' : ''}</p>${ft('doReopen', 'ยืนยัน')}`; break;
    case 'publish':
      size = 'sm'; h = `<h2>เผยแพร่ตารางเรียน ${esc(termLabel())}?</h2><p>อาจารย์และนักศึกษาจะดูตารางได้ที่หน้าตารางสาธารณะ จากนั้นส่งอีเมลแจ้งอาจารย์และ Export ไฟล์สำหรับ New ACIS ได้</p>${ft('doPublish', 'เผยแพร่')}`; break;
    case 'emailPreview': {
      const M = L.maps(ctx()); const ids = teachersWithSessions(); const t = M.T[f.tid] || {};
      const ents = (D.term.published ? D.term.published.entries : D.entries).filter(e => e.d != null && M.C[e.c] && M.C[e.c].teacher === f.tid).sort((a, b) => a.d - b.d || (a.h > b.h ? 1 : -1));
      const hrs = ents.reduce((s, e) => s + M.C[e.c].parts[e.p].hours, 0);
      h = `<button class="x" data-act="closeModal" aria-label="ปิด">${IC.xL}</button><h2 class="nb" style="margin-bottom:12px">ตัวอย่างอีเมลที่อาจารย์จะได้รับ</h2>
        <select class="inp" style="width:220px;margin-bottom:12px" data-act-change="emailPick">${ids.map(i => `<option value="${i}" ${i === f.tid ? 'selected' : ''}>${esc(M.T[i].name)}</option>`).join('')}</select>
        <div class="email">จาก CMMschedule<br>ถึง ${esc(t.name)} (${esc(t.email || 'ยังไม่มีอีเมล')})<br>หัวข้อ ตารางสอนภาคการศึกษา ${esc(termLabel())}<br><br>เรียน ${esc(t.name)}<br>ตารางสอนภาคการศึกษา ${esc(termLabel())} อาจารย์มีคาบการสอนทั้งหมด ${hrs} ชั่วโมงต่อสัปดาห์ ดังนี้<br>
        ${ents.map(e => { const co = M.C[e.c]; return `${esc(co.code)} ${L.DAYS[e.d]} ${L.timeLabel(co.parts[e.p].hours, e.h)} ห้อง ${e.r}`; }).join('<br>')}
        <button class="att" data-act="exportPDF" data-t="${f.tid}">${IC.pdf} ตารางสอน${esc(t.name)}.pdf</button></div>`;
      break;
    }
    case 'emailSend': {
      const ids = teachersWithSessions();
      h = `<h2>ส่ง Email แจ้งอาจารย์</h2><p class="small muted">เลือกอาจารย์ที่จะได้รับตารางสอน (แนบ PDF รายบุคคล)</p>
        ${ids.map(i => { const t = D.teachers.find(x => x.id === i); return `<label class="chk" style="display:flex"><input type="checkbox" data-act="emailToggle" data-id="${i}" ${f.sel.includes(i) ? 'checked' : ''} ${t.email ? '' : 'disabled'}>${esc(t.name)} <span class="small ${t.email ? 'muted' : 'bad-c'}">${esc(t.email || 'ยังไม่มีอีเมล · ให้พี่เมกเพิ่มในเงื่อนไขอาจารย์')}</span></label>`; }).join('')}
        ${Store.mode === 'cloud' && S.cfg && S.cfg.emailEnabled ? '<div class="banner info" style="margin:14px 0 0"><div class="grow small">ส่งอีเมลจริงผ่านเซิร์ฟเวอร์ (Resend) พร้อมแนบ PDF ตารางสอนรายบุคคล</div></div>' : `<div class="banner warn" style="margin:14px 0 0"><div class="grow small">ต้นแบบนี้ยังไม่ได้เชื่อมเซิร์ฟเวอร์อีเมลของภาควิชา จึงส่งจริงไม่ได้ ระบบจะบันทึกสถานะ "ส่งแล้ว (จำลอง)" เพื่อสาธิตขั้นตอน</div></div>`}
        ${ft('emailSendGo', 'ส่งอีเมล (' + f.sel.length + ')')}`; break;
    }
    case 'returnDraft': {
      const t = D.term; const M = L.maps(ctx()); const fx = Object.keys(t.review || {}).filter(k => t.review[k].s === 'fix');
      size = 'sm'; h = `<h2>ส่งกลับให้แก้ไข ${fx.length} คาบ</h2>${fx.map(k => { const e = D.entries.find(x => x.id === k); const co = e && M.C[e.c]; return co ? `<div class="condrow" style="font-size:14px"><span><b>${esc(co.code)}</b> ${esc(t.review[k].note || 'ต้องแก้ไข')}</span></div>` : ''; }).join('')}<p class="small muted">เจ้าหน้าที่จัดตารางจะได้รับแจ้งเตือนพร้อมหมายเหตุ</p>${ft('returnGo', 'ส่งกลับ')}`; break;
    }
    case 'confirmDraft':
      size = 'sm'; h = `<h2>ยืนยันตารางทั้งหมด?</h2><p>ทุกคาบผ่านการตรวจ ห้องเรียนพร้อมใช้งาน ระบบจะแจ้งเจ้าหน้าที่จัดตารางให้เผยแพร่ได้</p>${ft('confirmGo', 'ยืนยัน')}`; break;
    case 'reset':
      size = 'sm'; h = `<h2>รีเซ็ตข้อมูลสาธิต?</h2><p>ข้อมูลทั้งหมด (ห้อง อาจารย์ รายวิชา ตาราง การแจ้งเตือน) จะกลับเป็นค่าเริ่มต้น · ทุกเครื่องที่เปิดอยู่จะเห็นข้อมูลใหม่</p>${ft('resetGo', 'รีเซ็ต')}`; break;
    case 'csv':
      h = `<h2>คัดลอกข้อมูล</h2><p class="small muted">เบราว์เซอร์นี้ดาวน์โหลดไฟล์ไม่ได้ คัดลอกข้อมูลด้านล่างไปวางใน Excel ได้เลย</p><textarea class="inp" style="min-height:240px;font-size:12px" readonly>${esc(m.text)}</textarea><div class="ft"><button class="btn" data-act="csvCopy">คัดลอก</button><button class="btn ghost" data-act="closeModal">ปิด</button></div>`; break;
  }
  const lock = m.type === 'auto' && !m.res;
  return `<div class="modal-bg" ${lock ? '' : 'data-act="bgClose"'}><div class="modal ${size}" role="dialog" aria-modal="true">${h}</div></div>`;
}

/* ---------------- binding helpers ---------------- */
function rootOf(prefix) { return prefix === 'login' ? S.ui.login : prefix === 'form' ? S.ui.form : prefix === 'm' ? (S.ui.modal && S.ui.modal.f) : null; }
function setF(path, val) {
  const parts = path.split('.'); const root = rootOf(parts.shift()); if (!root) return;
  let o = root; for (let i = 0; i < parts.length - 1; i++) o = o[parts[i]];
  o[parts[parts.length - 1]] = val;
}
