async function importSave() {
  const m = S.ui.modal; const rows = m.rows; if (!rows) return;
  const idx = D.terms.findIndex(t => t.id === S.termId);
  let prev = null;
  for (let i = idx - 1; i >= 0 && !prev; i--) { const d = await Store.getOnce('courses/' + D.terms[i].id); if (d && d.list && d.list.length) prev = d.list; }
  const existing = D.courses; let nPrev = 0;
  const merged = existing.slice();
  rows.forEach(r => {
    const ex = merged.find(c => c.id === r.id);
    const base = { id: r.id, code: r.code, name: r.name, credit: r.credit || '', year: r.year, students: r.students, teacher: r.teacher, elective: r.elective };
    if (ex) { Object.assign(ex, base); return; }
    const pv = prev && prev.find(c => c.id === r.id);
    if (pv && pv.parts.length === r.parts.length) { nPrev++; merged.push(Object.assign({}, base, { parts: r.parts.map((p, i) => Object.assign({}, p, { type: pv.parts[i].type, equip: pv.parts[i].equip || [], room: pv.parts[i].room || '' })), note: pv.note || '', saved: true, fromPrev: true })); }
    else merged.push(Object.assign({}, base, { parts: r.parts, saved: false }));
  });
  if (m.newT && m.newT.length) mut('app/teachers', d => { d.list = (d.list || []).concat(m.newT); });
  Store.set('courses/' + S.termId, { list: merged });
  if (D.term) mutTerm(t => { logHist(t, 'นำเข้ารายวิชา ' + rows.length + ' วิชา'); });
  else Store.set('terms/' + S.termId, { id: S.termId, label: termLabel(), status: 'empty', entries: L.entriesFor(merged), version: 0, review: {}, fixLog: [], history: [] });
  const miss = merged.filter(c => !c.saved).length;
  addNotif('mek', 'นำเข้ารายวิชาภาค ' + termLabel() + ' ' + rows.length + ' วิชา' + (miss ? ' · รอบันทึกเงื่อนไขห้อง ' + miss + ' วิชา' : ''), 'mek-conditions');
  S.ui.modal = { type: 'importDone', n: rows.length, prev: nPrev, miss, f: {} }; scheduleRender();
}

