  unplace(el) { pushUndo(); S.ui.anim = true; mutTerm(t => { const e = t.entries.find(x => x.id === el.dataset.id); e.d = null; e.h = null; e.r = null; e.lock = false; }); S.ui.sel = null; toast('นำออกจากตารางแล้ว', '', { act: 'undo', label: 'ย้อนกลับ' }); },
