  emailSendGo() { const to = S.ui.modal.f.sel; if (!to.length) return; if (Store.mode === 'cloud' && S.cfg && S.cfg.emailEnabled) { sendEmailsCloud(to); return; } mutTerm(t => { t.emailSent = { at: Date.now(), to }; logHist(t, 'ส่งอีเมลแจ้งอาจารย์ (จำลอง) ' + to.length + ' ท่าน'); }); S.ui.modal = { type: 'saved', title: 'บันทึกการส่งอีเมลแล้ว', text: 'ส่ง (จำลอง) ถึงอาจารย์ ' + to.length + ' ท่าน พร้อมไฟล์ PDF ตารางสอนรายบุคคล', f: {} }; scheduleRender(); },
