  resetGo() { Store.seed(SEED.build(L)); Object.keys(Store.unsubs).filter(p => p.startsWith('terms/') || p.startsWith('courses/')).forEach(p => Store.unwatch(p)); S.termId = null; S.ui.undo = []; S.ui.pub = {}; S.ui.modal = null; S.ui.form = null; ensureTerm(); go(PAGES[S.session.role][0]); toast('รีเซ็ตข้อมูลสาธิตแล้ว'); },
  // import
