    if (!f.name.trim() || id.length < 4) { m.err = 'กรอกรหัสและชื่อวิชา'; return scheduleRender(); }
    if (f.isNew && D.courses.find(c => c.id === id)) { m.err = 'มีรหัสวิชานี้แล้ว'; return scheduleRender(); }
    f.students = +f.students || 1;
    mutCourses(list => { const i = list.findIndex(c => c.id === (f.isNew ? id : f.id)); const v = Object.assign({}, f, { id: f.isNew ? id : f.id }); delete v.isNew; if (f.isNew) v.saved = false; if (i >= 0) list[i] = Object.assign(list[i], v); else list.push(v); });
