    mut('app/globals', d => { d.list = d.list || []; const v = clone(f); delete v.isNew; if (f.isNew) { v.id = 'g' + uid(); d.list.push(v); } else { const i = d.list.findIndex(x => x.id === f.id); d.list[i] = v; } });
