    const A = L.analyze(ctx(), D.entries); const errs = (A.per[eid] || { errors: [] }).errors.map(x => x.text).join(' · ');
    mutTerm(t => { t.review = t.review || {}; const old = t.review[eid] || {}; t.review[eid] = { s, note: s === 'fix' ? (old.note || errs || '') : '', at: Date.now() }; });
