/* ---------------- drag & drop movement on the timetable ---------------- */
let drag = null;
document.addEventListener('pointerdown', e => {
  if (e.button !== 0) return;
  const b = e.target.closest('[data-drag]'); if (!b || !$('#tt-main')) return;
  drag = { eid: b.dataset.drag, el: b, x0: e.clientX, y0: e.clientY, started: false };
});
document.addEventListener('pointermove', e => {
  if (!drag) return;
  if (!drag.started) { if (Math.hypot(e.clientX - drag.x0, e.clientY - drag.y0) < 6) return; startDrag(e); }
  moveDrag(e);
});
document.addEventListener('pointerup', e => { if (!drag) return; if (drag.started) { endDrag(e); justDragged = true; setTimeout(() => { justDragged = false; }, 60); } drag = null; });
function startDrag(e) {
  drag.started = true;
  const c = ctx(); const M = L.maps(c); const ents = D.entries; const entry = ents.find(x => x.id === drag.eid); if (!entry) { drag = null; return; }
  const co = M.C[entry.c]; const p = co.parts[entry.p];
  const r = drag.el.getBoundingClientRect(); drag.rect = r;
  const isChip = drag.el.classList.contains('uchip');
  const g = isChip ? document.createElement('div') : drag.el.cloneNode(true);
  if (isChip) { g.className = 'blk'; g.innerHTML = `<div class="l1"><span class="code">${esc(co.code)}</span><span class="rp">${p.hours} ชม.</span></div><div class="l2"><span class="nm">${esc(co.name)}</span></div>`; }
  const w = isChip ? 220 : r.width;
  g.classList.add('dragghost'); g.classList.remove('sel', 'hl', 'appear'); g.style.cssText = `width:${w}px;height:64px;left:${e.clientX - (isChip ? 40 : e.clientX - r.left)}px;top:${e.clientY - (isChip ? 20 : e.clientY - r.top)}px`;
  g.insertAdjacentHTML('beforeend', '<span class="gt"></span>');
  drag.off = { x: isChip ? 40 : e.clientX - r.left, y: isChip ? 20 : e.clientY - r.top };
  document.body.appendChild(g); drag.ghost = g;
  if (!isChip) drag.el.classList.add('dim');
  document.body.classList.add('dragging');
  const v = vstate('sch', c);
  const others = ents.filter(o => o.id !== entry.id && o.d != null && o.r);
  $$('#tt-main .tt-row').forEach(row => {
    const d = +row.dataset.day; const track = $('.tt-track', row);
    L.HALVES.forEach(h => {
      let res;
      if (v.mode === 'room') res = { r: v.key, probs: L.placementProblems(c, M, others, entry, d, h, v.key) };
      else res = L.bestAt(c, ents, entry, d, h, entry.r);
      const [a, b] = L.partTime(p.hours, h);
      const z = document.createElement('div');
      z.className = 'zone ' + (res.probs.length ? 'bad' : 'ok');
      z.style.left = pct(a) + '%'; z.style.width = (pct(b) - pct(a)) + '%';
      z.dataset.d = d; z.dataset.h = h; z.dataset.r = res.r;
      z.dataset.label = L.DAYS[d] + ' ' + L.timeLabel(p.hours, h) + ' · ' + res.r;
      z.innerHTML = '<span>' + esc(res.probs.length ? '✗ ' + errShort(res.probs[0]) : '✓ ' + res.r) + '</span>';
      z.title = res.probs.map(x => x.text).join('\n');
      track.appendChild(z);
    });
  });
}
function moveDrag(e) {
  const g = drag.ghost; if (!g) return;
  g.style.left = (e.clientX - drag.off.x) + 'px'; g.style.top = (e.clientY - drag.off.y) + 'px';
  const hit = document.elementFromPoint(e.clientX, e.clientY); const z = hit && hit.closest('.zone');
  if (drag.over && drag.over !== z) drag.over.classList.remove('over');
  drag.over = z || null;
  const gt = $('.gt', g);
  if (z) { z.classList.add('over'); gt.textContent = (z.classList.contains('bad') ? '⚠ ' : '→ ') + z.dataset.label; gt.style.background = z.classList.contains('bad') ? 'var(--red)' : 'var(--navy)'; }
  else gt.textContent = 'ลากไปวางในช่องเวลา';
  const H = window.innerHeight; if (e.clientY < 90) window.scrollBy(0, -12); else if (e.clientY > H - 60) window.scrollBy(0, 12);
}
function cleanupDrag() { $$('.zone').forEach(z => z.remove()); document.body.classList.remove('dragging'); if (drag && drag.el) drag.el.classList.remove('dim'); }
function endDrag() {
  const z = drag.over; const g = drag.ghost; cleanupDrag();
  if (z) {
    S.ui.flipFrom = { id: drag.eid, rect: g.getBoundingClientRect() }; g.remove();
    doMove(drag.eid, +z.dataset.d, z.dataset.h, z.dataset.r);
  } else {
    const r = drag.rect; const gr = g.getBoundingClientRect();
    g.animate([{ left: gr.left + 'px', top: gr.top + 'px' }, { left: r.left + 'px', top: r.top + 'px', opacity: .3 }], { duration: 260, easing: 'ease-in' }).onfinish = () => g.remove();
  }
}
function cancelDrag() { if (drag.ghost) drag.ghost.remove(); cleanupDrag(); drag = null; }

/* ---------------- init ---------------- */
async function init() {
  scheduleRender();
  await Store.init();
  ['app/terms', 'app/rooms', 'app/teachers', 'app/globals', 'app/notifs'].forEach(p => Store.watch(p));
  if (Store.mode === 'local' && !Store.cache['app/terms']) Store.seed(SEED.build(L));
  route();
  const origRender = render;
  render = function () { ensureTerm(); origRender(); };
  scheduleRender();
  if (window.claude && typeof window.claude.use === 'function') {
    window.claude.use('downloads').then(d => { S.dl = d; }).catch(() => { });
    window.claude.use('user').then(async u => { S.user = u; if (u && u.can) { try { const can = await u.can('data.write'); if (can === false) { Store.readOnly = true; scheduleRender(); } } catch (e) { } } }).catch(() => { });
  }
}


/* CMMschedule — Supabase cloud mode (Vercel deploy)
   Used when /api/config returns a Supabase URL + anon key. Otherwise the app falls back to
   the browser-only (localStorage) mode, so index.html still works when opened as a file. */
const Cloud = {
  channel: null,
  ROLE_MAP: { admin: 'admin', room_officer: 'mek' },

  async detect() {
    if (!/^https?:/.test(location.protocol) || !window.supabase || !window.supabase.createClient) return null;
    try {
      const r = await fetch('/api/config', { cache: 'no-store' });
      if (!r.ok) return null;
      const cfg = await r.json();
      return cfg && cfg.supabaseUrl && cfg.supabaseAnonKey ? cfg : null;
    } catch (e) { return null; }
  },

  async start(cfg) {
    Store.mode = 'cloud'; Store.ver = {}; Store.fns = {}; S.cfg = cfg;
    Store.sb = window.supabase.createClient(cfg.supabaseUrl, cfg.supabaseAnonKey, { auth: { persistSession: true, autoRefreshToken: true } });
    S.session = null;
    try {
      const { data } = await Store.sb.auth.getSession();
      if (data && data.session) await Cloud.loadProfile(data.session.user, true);
    } catch (e) { }
    Store.sb.auth.onAuthStateChange((ev) => {
      if (ev === 'SIGNED_OUT') { S.session = null; LS.sset('cmm.session', null); scheduleRender(); }
      if (ev === 'TOKEN_REFRESHED' || ev === 'SIGNED_IN') Cloud.subscribe();
    });
    Cloud.subscribe();
    const refresh = () => { if (document.visibilityState === 'visible') Cloud.reloadAll(); };
    window.addEventListener('focus', refresh);
    document.addEventListener('visibilitychange', refresh);
  },

  async loadProfile(user, quiet) {
    const { data, error } = await Store.sb.from('profiles').select('role,name,title,email').eq('id', user.id).maybeSingle();
    if (error || !data || !Cloud.ROLE_MAP[data.role]) {
      if (!quiet) throw new Error('no_profile');
      return null;
    }
    S.session = { uid: user.id, email: user.email, role: Cloud.ROLE_MAP[data.role], name: data.name || user.email, title: data.title || '' };
    return S.session;
  },

  async login(f) {
    const email = String(f.email || '').trim().toLowerCase();
    f.err = ''; f.busy = true; scheduleRender();
    const fail = msg => { f.err = msg; f.shake = true; f.busy = false; scheduleRender(); setTimeout(() => { f.shake = false; }, 450); };
    const { data, error } = await Store.sb.auth.signInWithPassword({ email, password: f.pw || '' });
    if (error || !data.user) return fail('อีเมลหรือรหัสผ่านไม่ถูกต้อง');
    try { await Cloud.loadProfile(data.user); }
    catch (e) { await Store.sb.auth.signOut(); return fail('บัญชีนี้ยังไม่ได้กำหนดบทบาท (Admin หรือเจ้าหน้าที่ดูแลห้องเรียน)'); }
    S.ui.login = null; S.ui.form = null;
    await Cloud.reloadAll();
    Cloud.subscribe();
    ensureTerm(); go(PAGES[S.session.role][0]);
    toast('ยินดีต้อนรับ ' + S.session.name + (S.session.title ? ' · ' + S.session.title : ''));
  },

  // Live updates: one channel for the whole docs table; RLS decides what this user may receive.
  subscribe() {
    const sb = Store.sb; if (!sb) return;
    if (Cloud.channel) { try { sb.removeChannel(Cloud.channel); } catch (e) { } }
    Cloud.channel = sb.channel('cmm-docs')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'docs' }, p => Cloud.apply(p.new && p.new.path ? p.new : null))
      .subscribe();
  },

  apply(row) {
    if (!row || !(row.path in Store.unsubs)) return;
    const path = row.path;
    if (Store.busy[path] || Store.queue[path]) return;                 // our own write is in flight
    if ((Store.ver[path] || 0) >= (row.version || 0)) return;           // stale or our own echo
    Store.cache[path] = row.data; Store.ver[path] = row.version; Store.loaded[path] = true;
    scheduleRender();
  },

  async load(path) {
    const { data, error } = await Store.sb.from('docs').select('path,data,version').eq('path', path).maybeSingle();
    if (Store.busy[path] || Store.queue[path]) return;
    if (error) { Store.loaded[path] = true; Store.err = error; scheduleRender(); return; }
    if (data) { if ((Store.ver[path] || 0) <= data.version) { Store.cache[path] = data.data; Store.ver[path] = data.version; } }
    else { Store.cache[path] = null; Store.ver[path] = null; }
    Store.loaded[path] = true; scheduleRender();
  },

  async reloadAll() {
    const paths = Object.keys(Store.unsubs); if (!paths.length) return;
    const { data, error } = await Store.sb.from('docs').select('path,data,version').in('path', paths);
    if (error) return;
    const got = {}; (data || []).forEach(r => got[r.path] = r);
    paths.forEach(p => {
      if (Store.busy[p] || Store.queue[p]) return;
      const r = got[p];
      if (r) { if ((Store.ver[p] || 0) !== r.version) { Store.cache[p] = r.data; Store.ver[p] = r.version; } }
      else { Store.cache[p] = null; Store.ver[p] = null; }
      Store.loaded[p] = true;
    });
    scheduleRender();
  },

  // Save with optimistic locking. A stale write comes back as a conflict with the server copy;
  // the same changes (mutator functions) are re-applied on top of it and saved again.
  async flush(path) {
    if (Store.busy[path]) return; Store.busy[path] = true; Store.saving++; scheduleRender();
    let tries = 0;
    while (Store.queue[path]) {
      const job = Store.queue[path]; Store.queue[path] = null;
      const expected = job.fns.length ? (Store.ver[path] == null ? null : Store.ver[path]) : null;
      const { data, error } = await Store.sb.rpc('save_doc', { p_path: path, p_data: job.val, p_expected: expected });
      if (error) {
        const denied = /forbidden|not_allowed|42501|permission/i.test((error.message || '') + (error.code || ''));
        toast(denied ? 'บัญชีนี้ไม่มีสิทธิ์แก้ข้อมูลส่วนนี้' : 'บันทึกไม่สำเร็จ ลองอีกครั้ง', 'bad');
        Store.busy[path] = false; await Cloud.load(path); Store.busy[path] = true;
        continue;
      }
      if (data && data.ok) { Store.ver[path] = data.version; tries = 0; continue; }
      if (data && data.conflict && tries < 3) {
        tries++;
        const fresh = clone(data.data) || {};
        job.fns.forEach(fn => { try { fn(fresh); } catch (e) { } });
        fresh.updatedAt = Date.now();
        Store.ver[path] = data.version; Store.cache[path] = fresh;
        const later = Store.queue[path];
        Store.queue[path] = later ? { val: clone(later.val), fns: job.fns.concat(later.fns) } : { val: clone(fresh), fns: job.fns };
        if (later) { later.fns.forEach(fn => { try { fn(Store.queue[path].val); } catch (e) { } }); Store.cache[path] = Store.queue[path].val; }
        scheduleRender();
        continue;
      }
      if (data && data.conflict) { toast('มีคนแก้ข้อมูลนี้พร้อมกัน ระบบโหลดข้อมูลล่าสุดให้แล้ว', 'bad'); Store.busy[path] = false; await Cloud.load(path); Store.busy[path] = true; }
    }
    Store.busy[path] = false; Store.saving = Math.max(0, Store.saving - 1); Store.lastSaved = Date.now(); scheduleRender();
  }
};

/* ---- plug cloud mode into Store (falls back to the original behaviour in other modes) ---- */
(function () {
  const origInit = Store.init.bind(Store), origWatch = Store.watch.bind(Store), origGet = Store.getOnce.bind(Store), origSet = Store.set.bind(Store);
  Store.init = async function () {
    const cfg = await Cloud.detect();
    if (cfg) return Cloud.start(cfg);
    return origInit();
  };
  Store.watch = function (path) {
    if (this.mode !== 'cloud') return origWatch(path);
    if (this.unsubs[path]) return;
    this.unsubs[path] = () => { };
    Cloud.load(path);
  };
  Store.getOnce = async function (path) {
    if (this.mode !== 'cloud') return origGet(path);
    if (this.unsubs[path] && this.loaded[path]) return this.cache[path];
    const { data } = await this.sb.from('docs').select('data').eq('path', path).maybeSingle();
    return data ? clone(data.data) : null;
  };
  Store.set = function (path, val, fn) {
    if (this.mode !== 'cloud') return origSet(path, val);
    if (!S.session) { toast('เข้าสู่ระบบก่อนจึงจะบันทึกได้', 'bad'); return false; }
    val.updatedAt = Date.now();
    this.cache[path] = val;
    const prev = this.queue[path];
    this.queue[path] = { val: clone(val), fns: (prev ? prev.fns : []).concat(fn ? [fn] : []) };
    if (!fn) this.queue[path].fns = [];   // a whole-document write (seed, copy, import) overwrites
    Cloud.flush(path);
    return true;
  };
})();

init();
